\label{yinli-xuliekongjian}
The following assertions hold.
\begin{enumerate}
\item\label{xiang-touyingxingzhi} For every $\textbf{z}\in X$ and $n\in\mathbb{N}_0$, the projections in \eqref{shi-shouweitouying} satisfy
        \begin{equation}
            \|P_n\textbf{z}\|_X\leqslant\|\textbf{z}\|_X,
            \qquad
            \|Q_n\textbf{z}\|_X\leqslant\|\textbf{z}\|_X.
            \label{shi-shouweisuosuo}
        \end{equation}
        Moreover, for every
        $\textbf{z}\in\overline{\mathbb{C}^{(\mathbb{N})}}^{\,X}$,
        \begin{equation}
            \lim\limits_{n\to\infty}\|P_n\textbf{z}-\textbf{z}\|_X
            =
            \lim\limits_{n\to\infty}\|Q_n\textbf{z}\|_X
            =
            0.
            \label{shi-weibushoulian}
        \end{equation}

        \item\label{xiang-bibaokongjian}
        The space $\overline{\mathbb{C}^{(\mathbb{N})}}^{\,X}$
        equipped with the norm inherited from $X$ is a complex Banach sequence space.
        \item\label{xiang-wutiaojianji} The sequence $(e_i)_{i\in\mathbb{N}}$ is a $1$-unconditional Schauder basis of $X$ if and only if
    $
        X=\overline{\mathbb{C}^{(\mathbb{N})}}^{\,X}.
    $
        \item\label{xiang-kefenxing} The space $X$ is separable if and only if
    $
        X=\overline{\mathbb{C}^{(\mathbb{N})}}^{\,X}.
    $
    \end{enumerate}

\label{mingti-jishubiaoshi}
    Let $f\in H(O)$ and let
    $\textbf{z}_0\in O\cap\overline{\mathbb{C}^{(\mathbb{N})}}^{\,X}$ satisfy
    \begin{equation}
        \sum\limits_{\alpha\in\mathbb{N}_0^{(\mathbb{N})}}
        \left|c_{\alpha}(f)\textbf{z}_0^{\alpha}\right|<\infty.
        \label{shi-juduishoulianjiading}
    \end{equation}
    Then, for every $\textbf{z}\in\mathbb{C}^{\mathbb{N}}$ satisfying
    $|\textbf{z}|\leqslant|\textbf{z}_0|$, one has
    \begin{equation}
        \sum\limits_{\alpha\in\mathbb{N}_0^{(\mathbb{N})}}
        \left|c_{\alpha}(f)\textbf{z}^{\alpha}\right|<\infty,
        \label{shi-juduishoulian}
    \end{equation}
    and
    \begin{equation}
        f(\textbf{z})
        =
        \sum\limits_{\alpha\in\mathbb{N}_0^{(\mathbb{N})}}
        c_{\alpha}(f)\textbf{z}^{\alpha}.
        \label{shi-hanshubiaoshi}
    \end{equation}

\label{yinli-bituguji}
Let $O=X$ or $O=B_X$, and let
$\textbf{z}\in\mathrm{dom}H_b(O)$. There exist $A>0$ and $r>0$, with $r<1$ if $O=B_X$, such that for every
$f\in H_b(O)$,
\begin{equation}
	\sum\limits_{\alpha\in\mathbb{N}_0^{(\mathbb{N})}}
	|c_\alpha(f)\textbf{z}^\alpha|
	\leqslant A\|f\|_r .
	\label{shi-bituguji}
\end{equation}
In particular, if $O=X$, there is $K\geqslant1$ such that for every
$m\in\mathbb{N}, P\in\mathcal{P}^m(X)$,
\begin{equation}
\sum\limits_{|\alpha|=m}|c_\alpha(P)\textbf{z}^\alpha|
\leqslant K^m\|P\|_{\mathcal{P}^m(X)}.
\label{shi-dianchuzhishijie}
\end{equation}

\label{dingli-ercizhangai}
    If $\mathbb{C}^{(\mathbb{N})}$ is not dense in $X$, then  for each $\textbf{x} \in X\setminus \overline{\mathbb{C}^{(\mathbb{N})}}^{\,X}$, there exists
    $G\in\mathcal{P}^{2}(X)$ such that
    \begin{equation}
        \sum\limits_{\substack{
                \alpha\in\mathbb{N}_0^{(\mathbb{N})}\\
                |\alpha|=2
        }}
        \left|c_{\alpha}(G)\textbf{x}^{\alpha}\right|
        =+\infty.
        \label{shi-ercifasan}
    \end{equation}

\label{zhuji-bibaobaohan}
For every Reinhardt domain $O\subset X$, Theorem~\ref{dingli-ercizhangai} gives for each $\mathcal{P}^{2} \left( X \right) \subset \mathcal{F} \left( O \right) \subset H\left( O \right)$,
\begin{equation}
\mathrm{dom} \mathcal{F}(O)
\subset\overline{\mathrm{span}\{e_j:j\geqslant1\}}^{\,X}.
\label{shi-bibaobaohan}
\end{equation}
This gives an affirmative answer
to Problem~\ref{wenti-bibaobaohan}.

\label{yinli-weibuguji}
	Suppose that $\overline{\mathbb{C}^{(\mathbb{N})}}^{\,X}=X$ and
	$\textbf{z}\in\mathrm{dom}H(X)$. For every $r>0$, there exist
	$N\in\mathbb{N}$ and $C>0$ such that for every $n\geqslant N, p\in\mathscr{P}_n$,
\begin{equation}
	\sum\limits_{\alpha\in\mathbb{N}_0^{(\mathbb{N})}}
	|c_\alpha(p)\textbf{z}^\alpha|
	\leqslant C\|p\|_r.
	\label{shi-weibutongyijie}
\end{equation}

\label{mingti-jubuhua}
Suppose that $\overline{\mathbb{C}^{(\mathbb{N})}}^{\,X}=X$.
For every Reinhardt domain $O\subset X$,
\begin{equation}
\mathrm{dom}H(O)=O\cap\mathrm{dom}H(X).
\label{shi-jubuhua}
\end{equation}
More precisely, for each $\textbf{z}\in O$ the following conditions
are equivalent:
\begin{enumerate}
\item\label{xiang-yuneishoulian} $\textbf{z}\in\mathrm{dom}H(O)$.
\item\label{xiang-zhenghanshushoulian} $\textbf{z}\in\mathrm{dom}H(X)$.
\item\label{xiang-weibupanju} For every $r>0$, there exist $N\in\mathbb{N}$ and $C>0$ such that
\begin{equation}
\sum\limits_{\alpha\in\mathbb{N}_0^{(\mathbb{N})}}
|c_\alpha(p)\textbf{z}^\alpha|
\leqslant C\|p\|_r,
\qquad p\in\mathscr{P}_N.
\label{shi-weibupanju}
\end{equation}
\end{enumerate}

\label{yinli-feijiebijin}
Let $\textbf{z}\in X$, $n\in\mathbb{N}_0$, and $r,C>0$.
Suppose that
\begin{equation}
	\sum\limits_{\alpha\in\mathbb{N}_0^{(\mathbb{N})}}
	|c_\alpha(p)\textbf{z}^{\alpha}|
	\leqslant C\|p\|_r,
	\qquad p\in\mathscr{P}_n.\label{shi-weibubijinjiading}
\end{equation}
Then
\begin{equation}
\sum\limits_{\beta\in\Lambda_n}
|c_\beta(g)(Q_n\textbf{z})^\beta|
\leqslant C\|g\|_\infty,
\qquad g\in H^\infty(rB_{Y_n}).
\label{shi-weibuquanchunguji}
\end{equation}

For $m>n$ and $d\in\mathbb{N}_0$, put
$$
p_{m,d}(\textbf{x})
\triangleq
\sum\limits_{\substack{\beta\in\Lambda_n\\
\mathrm{supp}\beta\subset\{n+1,\cdots,m\}\\
|\beta|\leqslant d}}
\left(1-\frac{|\beta|}{d+1}\right)
c_\beta(g)\textbf{x}^\beta\in\mathscr{P}_n.
$$
Define
$$
K_d(\theta)
\triangleq
\frac{1}{d+1}\left|\sum\limits_{k=0}^{d}e^{\mathrm{i}k\theta}\right|^2,
\qquad \theta\in[0,2\pi].
$$
We have
\begin{equation}
    K_d(\theta)
    =
    \sum\limits_{\ell=-d}^{d}
    \left(1-\frac{|\ell|}{d+1}\right)e^{\mathrm{i}\ell\theta},
    \qquad
    K_d\geqslant0,
    \qquad
    \frac{1}{2\pi}\int\limits_0^{2\pi}K_d(\theta)\,\mathrm{d}\theta=1,\label{shi-feijiehe}
\end{equation}
and for each $k\in\mathbb{N}_0$, 
\begin{equation}\label{shi-feijiexishu}
    \begin{aligned}
        \frac{1}{2\pi}\int\limits_0^{2\pi}
        K_d(\theta)e^{\mathrm{i}k\theta}\,\mathrm{d}\theta
        &=\sum\limits_{\ell=-d}^{d}\left(1-\frac{|\ell|}{d+1}\right)
        \frac{1}{2\pi}\int\limits_0^{2\pi}
        e^{\mathrm{i}(\ell+k)\theta}\,\mathrm{d}\theta=
        \begin{cases}
            1-\frac{k}{d+1},&0\leqslant k\leqslant d,\\[2pt]
            0,&k>d.
        \end{cases}
    \end{aligned}
\end{equation}

Fix $g\in H^\infty(rB_{Y_n})$. For $\textbf{x}\in rB_X$, by \eqref{shi-feijiexishu}, we have
\begin{equation}\label{shi-feijiejifen}
	\begin{aligned}
		p_{m,d}(\textbf{x})
		&=
		\sum\limits_{\substack{\beta\in\Lambda_n\\
				\mathrm{supp}\beta\subset\{n+1,\cdots,m\}\\
				|\beta|\leqslant d}}
		\left(1-\frac{|\beta|}{d+1}\right)
		c_\beta(g)\textbf{x}^\beta\\
		&=
		\frac{1}{2\pi}
		\sum\limits_{\substack{\beta\in\Lambda_n\\
				\mathrm{supp}\beta\subset\{n+1,\cdots,m\}}}
		c_\beta(g)\textbf{x}^\beta
		\int\limits_0^{2\pi}
		K_d(\theta)e^{\mathrm{i}|\beta|\theta}\,\mathrm{d}\theta\\
		&=
		\frac{1}{2\pi}\int\limits_0^{2\pi}
		K_d(\theta)
		\sum\limits_{\substack{\beta\in\Lambda_n\\
				\mathrm{supp}\beta\subset\{n+1,\cdots,m\}}}
		c_\beta(g)
		\bigl(e^{\mathrm{i}\theta}(P_m-P_n)\textbf{x}\bigr)^\beta
		\,\mathrm{d}\theta\\
		&=
		\frac{1}{2\pi}\int\limits_0^{2\pi}
		K_d(\theta)\,
		g\bigl(e^{\mathrm{i}\theta}(P_m-P_n)\textbf{x}\bigr)
		\,\mathrm{d}\theta.
	\end{aligned}
\end{equation}
By \eqref{shi-feijiehe} and \eqref{shi-feijiejifen},
for every $\textbf{x}\in rB_X$,
$$
\begin{aligned}
|p_{m,d}(\textbf{x})|
&\leqslant\frac{1}{2\pi}\int\limits_0^{2\pi}
 K_d(\theta)
 \left|g\bigl(e^{\mathrm{i}\theta}(P_m-P_n)\textbf{x}\bigr)\right|
 \,\mathrm{d}\theta\leqslant\frac{\|g\|_\infty}{2\pi}
\int\limits_0^{2\pi}K_d(\theta)\,\mathrm{d}\theta
=\|g\|_\infty,
\end{aligned}
$$
which gives $\|p_{m,d}\|_r\leqslant\|g\|_\infty$. Thus
\eqref{shi-weibubijinjiading} gives
$$
\sum\limits_{\substack{\beta\in\Lambda_n\\
\mathrm{supp}\beta\subset\{n+1,\cdots,m\}\\
|\beta|\leqslant d}}
\left(1-\frac{|\beta|}{d+1}\right)
|c_\beta(g)(Q_n\textbf{z})^\beta|\leqslant C\| p_{m,d}\|_{r}
\leqslant C\|g\|_\infty.
$$
Letting $m,d\to\infty$ gives 
\eqref{shi-weibuquanchunguji}.

\label{tuilun-quanyushoulian}
If
\begin{equation}
\mathrm{dom}H(B_X)=B_X,
\label{shi-qiushoulianjiading}
\end{equation}
then, for every Reinhardt domain $O\subset X$,
\begin{equation}
\mathrm{dom}H(O)=O.
\label{shi-quanyushoulian}
\end{equation}

\label{dingli-shoulianpanju}
One has
\begin{equation}
\mathrm{dom}H(X)=X
\label{shi-zhenghanshuquanshoulian}
\end{equation}
if and only if there exists $C\geqslant1$ such that, for every
$m,n\in\mathbb{N}$ and every $P\in\mathcal{P}^m(X)$ satisfying
$P=P\circ P_n$,
\begin{equation}
\sup\limits_{\textbf{z}\in B_X}
\sum\limits_{\substack{\alpha\in\mathbb{N}_0^{(\mathbb{N})}\\|\alpha|=m}}
|c_\alpha(P)\textbf{z}^\alpha|
\leqslant C^m\sup\limits_{\textbf{z}\in B_X}|P(\textbf{z})|.
\label{shi-tongyizhishiguji}
\end{equation}
Here $P_n$ is given on all of $X$ by the formula in \eqref{shi-shouweitouying},
and $C$ is independent of $m$, $n$, and $P$.

\label{yinli-gujituiguang}
Suppose that there is $C\geqslant1$ such that \eqref{shi-tongyizhishiguji} holds for every $m,n\in\mathbb{N}$ and every $P\in\mathcal{P}^m(X)$ satisfying $P=P\circ P_n$. Then, for every $m\in\mathbb{N}$, $P\in\mathcal{P}^m(X)$, and $\textbf{z}\in X$,
\begin{equation}
\sum\limits_{|\alpha|=m}|c_\alpha(P)\textbf{z}^\alpha|
\leqslant C^m\|\textbf{z}\|_X^m
\sup\limits_{\textbf{w}\in B_X}|P(\textbf{w})|.
\label{shi-yibanduoxiangshijie}
\end{equation}
Moreover, $\overline{\mathbb{C}^{(\mathbb{N})}}^{\,X}=X$.

\label{dingyi-fanlikongjian}
    Define
    \begin{equation}
        a_0\triangleq 1,
        \qquad
        a_r\triangleq 2^{a_{r-1}+1},
        \qquad r=1,2,\cdots.
        \label{shi-cengjicanshu}
    \end{equation}
    For $r=1,2,\cdots$, set
    \begin{equation}
        \kappa(r)
        \triangleq
        \max\left\{
        j\in\mathbb{N}_0:a_j\leqslant r
        \right\}.
        \label{shi-cengjisuoyin}
    \end{equation}

Given a nondecreasing function
$
    \Psi:\mathbb{N}\longrightarrow[1,+\infty)
  $
    satisfying
$
    \lim\limits_{n\to\infty}\Psi(n)=+\infty,
$
    define inductively
    \begin{equation}
        t_0\triangleq 1, t_r
        \triangleq
        \min\left\{
        \left(1+\frac{1}{r}\right)t_{r-1},
        \,2t_{\kappa(r)},
        \,\Psi(a_{r-1})
        \right\},
        \qquad r=1,2,\cdots.
        \label{shi-huanmancanshu}
    \end{equation}

    For each $r\in\mathbb{N}_0$, define
    \begin{equation}
        \mathcal{G}_r
        \triangleq
        \left\{
        \frac{t_r}{a_r}
        \sum\limits_{j\in F}\epsilon_j e_j:
        F\subset\mathbb{N},
        \ |F|=a_r,
        \ \epsilon_j\in\{-1,1\}
        \ \text{for every }j\in F
        \right\},
        \qquad
        \mathcal{G}
        \triangleq
        \bigcup\limits_{r\in\mathbb{N}_0}\mathcal{G}_r.
        \label{shi-yuanziji}
    \end{equation}
    For $\textbf{z}\in\mathbb{C}^{(\mathbb{N})}$, define
    $$
    \|\textbf{z}\|_Y
    \triangleq
    \inf
    \left\{
    \sum\limits_{v=1}^{s}|\lambda_v|:
    \begin{array}{l}
        s\in\mathbb{N},\;
        \lambda_v\in\mathbb{R},\;
        \textbf{u}_v\in\mathcal{G},\quad v=1,\cdots,s,\\[2mm]
        |\textbf{z}|=\displaystyle\sum\limits_{v=1}^{s}\lambda_v\textbf{u}_v
    \end{array}
    \right\}.
    $$

\label{yinli-canshuxingzhi}
The sequence $(t_r)_{r\in \mathbb{N}_{0}}$ defined by \eqref{shi-huanmancanshu} satisfies for every $r\in\mathbb{N}$,
\begin{align}
1&\leqslant t_{r-1}\leqslant t_r\leqslant r+1,
\label{shi-huanmancanshujie}\\
\frac{t_r}{a_r}&\leqslant\frac{1}{2}\frac{t_{r-1}}{a_{r-1}}\leqslant\frac{1}{2},
\label{shi-yuanzigaodu}\\
\lim\limits_{r\to +\infty} t_{r}&=+\infty,\label{shi-jixian}
\end{align}

\label{yinli-fanshugouzao}
The expression $\|\cdot\|_Y$ in Definition~\ref{dingyi-fanlikongjian} defines a norm on $\mathbb{C}^{(\mathbb{N})}$ satisfying
\begin{equation}
\|\textbf{z}\|_{\ell^\infty}\leqslant\|\textbf{z}\|_Y\leqslant\|\textbf{z}\|_{\ell^1},
\qquad \textbf{z}\in\mathbb{C}^{(\mathbb{N})}.
\label{shi-fanlifanshubijiao}
\end{equation}
Moreover, whenever $\textbf{x},\textbf{y}\in\mathbb{C}^{(\mathbb{N})}$ and $|\textbf{x}|\leqslant|\textbf{y}|$,
\begin{equation}
\|\textbf{x}\|_Y\leqslant\|\textbf{y}\|_Y.
\label{shi-fanlifanshudandiao}
\end{equation}

\label{dingyi-fanlikongjian-Y}
	Define
	$$
	Y
	\triangleq
	\left\{
	\textbf{z}\in c_0:
	(P_n\textbf{z})_{n\in\mathbb{N}}
	\text{ is a Cauchy sequence in }
	(\mathbb{C}^{(\mathbb{N})},\|\cdot\|_{Y})
	\right\}.
	$$
	For $\textbf{z}\in Y$, put
	\begin{equation}
		\|\textbf{z}\|_Y
		\triangleq
		\lim\limits_{n\to\infty}\|P_n\textbf{z}\|_{Y}.
		\label{shi-fanlikongjianfanshu}
	\end{equation}

\label{mingti-fanlixingzhi}
Let $Y$ be the space defined in Definition~\ref{dingyi-fanlikongjian-Y}. Then the following
assertions hold.
\begin{enumerate}
\item\label{xiang-fanlikongjian}
$Y$ is a complex Banach sequence space and
$\mathbb{C}^{(\mathbb{N})}$ is dense in $Y$.

\item\label{xiang-duichenji}
$(e_j)_{j\in\mathbb{N}}$ is a normalized $1$-symmetric Schauder basis
of $Y$. More precisely, $\|e_j\|_Y=1$ for every $j\in\mathbb{N}$, and
\begin{equation}
\left\|\sum\limits_{j=1}^{n}\omega_jz_je_{\pi(j)}\right\|_Y
=
\left\|\sum\limits_{j=1}^{n}z_je_j\right\|_Y
\label{shi-zhihuanxiangwei}
\end{equation}
for every $n\in\mathbb{N}$, every permutation $\pi$ of $\mathbb{N}$,
and all $z_j,\omega_j\in\mathbb{C}$ with $|\omega_j|=1$,
$j=1,\cdots,n$. 

\item\label{xiang-shibuyuxubu}
For every $\textbf{z}\in Y$,
\begin{equation}
|\textbf{z}|
\in Y\cap\mathbb{R}^{\mathbb{N}},
\qquad
\left\||\textbf{z}|\right\|_Y=\|\textbf{z}\|_Y.
\label{shi-qumobaofan}
\end{equation}
Moreover,
\begin{equation}
\left\{\textbf{x}\in Y\cap\mathbb{R}^{\mathbb{N}}:
\|\textbf{x}\|_Y\leqslant1\right\}
=
\overline{\mathrm{conv}\mathcal{G}}^{\,Y},
\label{shi-shiqiutubao}
\end{equation}
where $\mathrm{conv}\mathcal{G}$ denotes the set of finite
convex combinations of elements of $\mathcal{G}$.

\end{enumerate}

\label{mingti-jibenhanshu}\label{mingti-jiejinyikehe}
Define
$$
\varphi(n)\triangleq
\left\|\sum\limits_{j=1}^{n}e_j\right\|_Y,
\qquad n\in\mathbb{N}.
$$
Then, for every nonempty finite set $F\subset\mathbb{N}$ and every
choice of $\omega_j \in \mathbb{C}$ with $|\omega_j|=1$, $j\in F$,
\begin{equation}
\left\|\sum\limits_{j\in F}\omega_je_j\right\|_Y=\varphi(|F|).
\label{shi-xiangweifanshu}
\end{equation}
Moreover,
\begin{equation}
\varphi(a_r)=\frac{a_r}{t_r},
\qquad r\in\mathbb{N}_0,
\label{shi-yuanzifanshu}
\end{equation}
and for all $n\geqslant a_{r-1},n,r\in\mathbb{N}$,
\begin{equation}
t_r\leqslant\frac{2r}{\varphi(r)},
\qquad
\varphi(n)\leqslant\frac{n}{t_{r-1}}.
\label{shi-canshuyujibenhanshu}
\end{equation}
For every
$n\in\mathbb{N}$ and every $\textbf{z}\in Y$ satisfying
$|\mathrm{supp}\textbf{z}|\leqslant n$, it holds that
\begin{equation}
\frac{1}{\Psi(n)}\|\textbf{z}\|_{\ell^1}
\leqslant\|\textbf{z}\|_Y\leqslant\|\textbf{z}\|_{\ell^1}.
\label{shi-youxianweibijiao}
\end{equation}

\label{tuilun-yangeqianru}\label{tuilun-jiruoshoulian}
The inclusions
$$
\ell^1\subsetneq Y\subsetneq c_0
$$
are continuous, and
\begin{equation}
\|e_j\|_Y=1,\qquad j\in\mathbb{N},
\qquad
e_j\rightharpoonup0\quad\text{in }Y.
\label{shi-jiruoshoulian}
\end{equation}

\label{yinli-zhichijishu}
Let $m,d\in\mathbb{N},P\in \mathscr{P}_0\cap \mathcal{P}^{m} \left( Y\right)$ and let $\textbf{z}\in \mathbb{C}^{(\mathbb{N})}$ with $\left| \mathrm{supp} \textbf{z} \right| =d$. Then
\begin{equation}
P^{\#}(|\textbf{z}|)
\leqslant\binom{m+d-1}{m}^{\frac{1}{2}}\|P\|_{\mathcal{P}^m(Y)}\|\textbf{z}\|_Y^m.
\label{shi-zhichijishu}
\end{equation}

Without loss of generality, assume that $\textbf{z} \neq \textbf{0}$ and let $\mathrm{supp}\textbf{z}=\{j_1,\cdots,j_d\}$.  Consider $\textbf{x}=\left( x_{i} \right)_{i\in \mathbb{N}}\triangleq\frac{|\textbf{z}|}{\|\textbf{z}\|_Y}$.  Clearly, \eqref{shi-zhichijishu} is equivalent to
\begin{equation}
	P^{\#}(\textbf{x})\leqslant\binom{m+d-1}{m}^{\frac{1}{2}}\|P\|_{\mathcal{P}^m(Y)}.\label{shi-11}
\end{equation}
Consider
\begin{equation}
	\mathcal{A}\triangleq
	\{\alpha\in\mathbb{N}_0^{(\mathbb{N})}:|\alpha|=m,\ \mathrm{supp}\alpha\subset \mathrm{supp}\textbf{z}\},
	\qquad |\mathcal{A}|=\binom{m+d-1}{m}.
	\label{shi-danxiangshishu}
\end{equation}
We have
\begin{equation}
	\begin{aligned}
		&\frac{1}{(2\pi )^{d}} \int\limits_{[0,2\pi ]^{d}} \left| P\left( \sum\limits_{\ell =1}^{d} x_{j_{\ell}}e^{\mathrm{i} \theta_{\ell}}e_{j_{\ell}} \right) \right|^{2} \mathrm{d} \theta_{1} \cdots \mathrm{d} \theta_{d}\\ &\  =\frac{1}{(2\pi )^{d}} \int\limits_{[0,2\pi ]^{d}} \left| \sum\limits_{\alpha \in \mathcal{A}} c_{\alpha}(P)\textbf{x}^{\alpha} e^{\mathrm{i} \sum\limits_{\ell =1}^{d} \alpha_{j_{\ell}} \theta_{\ell}} \right|^{2} \mathrm{d} \theta_{1} \cdots \mathrm{d} \theta_{d}\\ &\  =\frac{1}{(2\pi )^{d}} \sum\limits_{\alpha ,\beta \in \mathcal{A}} c_{\alpha}(P)\overline{c_{\beta}(P)} \textbf{x}^{\alpha +\beta} \int\limits_{[0,2\pi ]^{d}} e^{\mathrm{i} \sum\limits_{\ell =1}^{d} (\alpha_{j_{\ell}} -\beta_{j_{\ell}} )\theta_{\ell}}\mathrm{d} \theta_{1} \cdots \mathrm{d} \theta_{d}\\ &\  =\frac{1}{(2\pi )^{d}} \sum\limits_{\alpha \in \mathcal{A}} \left| c_{\alpha}(P) \right|^{2} \textbf{x}^{2\alpha} \int\limits_{[0,2\pi ]^{d}} 1\mathrm{d} \theta_{1} \cdots \mathrm{d} \theta_{d} =\sum\limits_{\alpha \in \mathcal{A}} \left| c_{\alpha}(P) \right|^{2} \textbf{x}^{2\alpha}\\ &\  \leqslant \frac{1}{(2\pi )^{d}} \int\limits_{[0,2\pi ]^{d}} \|P\|_{\mathcal{P}^{m} \left( Y \right)}^{2} \cdot \left\| \sum\limits_{\ell =1}^{d} x_{j_{\ell}}e^{\mathrm{i} \theta_{\ell}}e_{j_{\ell}} \right\|_{Y}^{2m} \mathrm{d} \theta_{1} \cdots \mathrm{d} \theta_{d}\\ &\  =\frac{1}{(2\pi )^{d}} \int\limits_{[0,2\pi ]^{d}} \|P\|_{\mathcal{P}^{m} \left( Y \right)}^{2} \cdot \|\textbf{x}\|_{Y}^{2m} \mathrm{d} \theta_{1} \cdots \mathrm{d} \theta_{d} =\|P\|_{\mathcal{P}^{m} \left( Y \right)}^{2},\end{aligned}
	\label{shi-xishupingfanghe}
\end{equation}
where the penultimate equality follows from \eqref{shi-qumobaofan}.  Then the Cauchy--Schwarz inequality, \eqref{shi-danxiangshishu}, and \eqref{shi-xishupingfanghe} give
\begin{equation}
	\begin{aligned}
		P^{\#}(\textbf{x})
		&=\sum\limits_{\alpha\in\mathcal{A}}|c_\alpha(P)|\textbf{x}^\alpha
		\leqslant|\mathcal{A}|^{\frac{1}{2}}
		\left(\sum\limits_{\alpha\in\mathcal{A}}|c_\alpha(P)|^2\textbf{x}^{2\alpha}\right)^{\frac{1}{2}}\leqslant\binom{m+d-1}{m}^{\frac{1}{2}}\|P\|_{\mathcal{P}^m(Y)},
	\end{aligned}
	\label{shi-xishuhepingfangjie}
\end{equation}
which gives \eqref{shi-zhichijishu}.

\label{yinli-suijixishuhua}
Let $m\in\mathbb{N}$ and let $P\in \mathscr{P}_0\cap \mathcal{P}^{m} \left( Y\right)$. 
$\textbf{x}=\left( x_{i} \right)_{i\in \mathbb{N}}\in\mathbb{C}^{(\mathbb{N})}\cap[0,+\infty)^{\mathbb{N}}$
satisfies \begin{equation}
P^{\#}(\textbf{x})
\leqslant\frac{m^m}{m!}\binom{3m-1}{m}^{\frac{1}{2}}
\left(\|\textbf{x}\|_Y+
\frac{\varphi(m)}{m}\|\textbf{x}\|_{\ell^1}\right)^m
\|P\|_{\mathcal{P}^m(Y)}.
\label{shi-xishuhuaguji}
\end{equation}

Without loss of generality, assume that $\textbf{x} \neq \textbf{0}$. Put
\begin{equation}
	I\triangleq
	\left\{j\in \mathbb{N}:x_j\geqslant\frac{\|\textbf{x}\|_{\ell^1}}{m}\right\},
	\qquad
	J\triangleq
	\left\{j\in \mathbb{N}:0<x_j<\frac{\|\textbf{x}\|_{\ell^1}}{m}\right\}.
	\label{shi-daxiaozuobiao}
\end{equation}
Then $I\cup J=\mathrm{supp}\textbf{x}$ is finite. Moreover,
$$
\frac{\|\textbf{x}\|_{\ell^1}}{m}|I|
\leqslant\sum\limits_{j\in I}x_j
\leqslant\|\textbf{x}\|_{\ell^1},
$$
and hence $|I|\leqslant m$. For
$(i_1,\cdots,i_m)\in(J\cup\{0\})^m$, define
\begin{equation}
	\begin{aligned}	\lambda_{i_1,\cdots,i_m}&\triangleq
		\left(
		1-\sum\limits_{j\in J}\frac{x_j}{\|\textbf{x}\|_{\ell^1}}
		\right)^{|\{1\leqslant \nu \leqslant m:i_\nu=0\}|}
		\prod\limits_{\substack{1\leqslant\nu\leqslant m\\ i_\nu\neq0}}
		\frac{x_{i_\nu}}{\|\textbf{x}\|_{\ell^1}},\\F_{i_1,\cdots,i_m}&	\triangleq\{i_\nu:1\leqslant\nu\leqslant m,\ i_\nu\neq0\},\end{aligned}
	\label{shi-quanzhongzhichi}
\end{equation}
and set
\begin{equation}
	\textbf{y}_{i_1,\cdots,i_m}
	\triangleq
	\sum\limits_{j\in I}x_je_j+
	\frac{\|\textbf{x}\|_{\ell^1}}{m}
	\sum\limits_{j\in F_{i_1,\cdots,i_m}}e_j.
	\label{shi-xishuxiangliang}
\end{equation}
Since
$
0\leqslant
\sum\limits_{j\in J}\frac{x_j}{\|\textbf{x}\|_{\ell^1}}
\leqslant1,
$
all $\lambda_{i_1,\cdots,i_m}$ are nonnegative, and 
\begin{equation}
	\begin{aligned}
		\sum\limits_{(i_1,\cdots,i_m)\in(J\cup\{0\})^m}
		\lambda_{i_1,\cdots,i_m}
		&=
		\left(
		1-\sum\limits_{j\in J}\frac{x_j}{\|\textbf{x}\|_{\ell^1}}
		+\sum\limits_{j\in J}\frac{x_j}{\|\textbf{x}\|_{\ell^1}}
		\right)^m
		=1.
	\end{aligned}
	\label{shi-quanzhongweiyi}
\end{equation}
For every $(i_1,\cdots,i_m)\in(J\cup\{0\})^m$, one has
$|F_{i_1,\cdots,i_m}|\leqslant m$. Thus, by \eqref{shi-fanshudandiao} and \eqref{shi-xiangweifanshu},
\begin{equation}
	\begin{aligned}
		|\mathrm{supp}\textbf{y}_{i_1,\cdots,i_m}|
		&\leqslant|I|+|F_{i_1,\cdots,i_m}|
		\leqslant2m,\\
		\|\textbf{y}_{i_1,\cdots,i_m}\|_Y
		&\leqslant
		\left\|\sum\limits_{j\in I}x_je_j\right\|_Y
		+\frac{\|\textbf{x}\|_{\ell^1}}{m}
		\left\|\sum\limits_{j\in F_{i_1,\cdots,i_m}}e_j\right\|_Y\\
		&\leqslant
		\|\textbf{x}\|_Y+
		\frac{\varphi(m)}{m}\|\textbf{x}\|_{\ell^1}.
	\end{aligned}
	\label{shi-xishufanshujie}
\end{equation}

Fix $\alpha\in\mathbb{N}_0^{(\mathbb{N})}$ with $|\alpha|=m$ and
$\textbf{x}^{\alpha}>0$, and put
$
S\triangleq J\cap\mathrm{supp}\alpha.
$
Define
$$
\mathcal I_S
\triangleq
\left\{
(i_1,\cdots,i_m)\in(J\cup\{0\})^m:
\left| \{ \nu \in \{ 1,\cdots ,m\} :i_{\nu}=j\} \right|=1
\ \text{for every }j\in S
\right\}.
$$
Then, by \eqref{shi-quanzhongzhichi},
\begin{align}
	\sum\limits_{(i_1,\cdots,i_m)\in\mathcal I_S}
	\lambda_{i_1,\cdots,i_m}
	&=
	\frac{m!}{(m-|S|)!}
	\prod\limits_{j\in S}
	\frac{x_j}{\|\textbf{x}\|_{\ell^1}}
	\nonumber\\
	&\quad\times
	\sum\limits_{\substack{
			(i_1,\cdots,i_{m-|S|})\\
			\in((J\setminus S)\cup\{0\})^{m-|S|}
	}}
	\prod\limits_{\substack{1\leqslant \nu\leqslant m-|S|\\ i_\nu=0}}
	\left(
	1-\sum\limits_{j\in J}
	\frac{x_j}{\|\textbf{x}\|_{\ell^1}}
	\right)
	\prod\limits_{\substack{1\leqslant \nu\leqslant m-|S|\\ i_\nu\neq0}}
	\frac{x_{i_\nu}}{\|\textbf{x}\|_{\ell^1}}
	\nonumber\\
	&=
	\frac{m!}{(m-|S|)!}
	\prod\limits_{j\in S}
	\frac{x_j}{\|\textbf{x}\|_{\ell^1}}
	\left(
	1-\sum\limits_{j\in J}
	\frac{x_j}{\|\textbf{x}\|_{\ell^1}}
	+
	\sum\limits_{j\in J\setminus S}
	\frac{x_j}{\|\textbf{x}\|_{\ell^1}}
	\right)^{m-|S|}
	\nonumber\\
	&=
	\frac{m!}{(m-|S|)!}
	\prod\limits_{j\in S}
	\frac{x_j}{\|\textbf{x}\|_{\ell^1}}
	\left(
	1-\sum\limits_{j\in S}
	\frac{x_j}{\|\textbf{x}\|_{\ell^1}}
	\right)^{m-|S|}.
	\label{shi-zhidingzuobiaoquan}
\end{align}
By \eqref{shi-daxiaozuobiao},
$
\sum\limits_{j\in S}\frac{x_j}{\|\textbf{x}\|_{\ell^1}}
\leqslant\frac{|S|}{m},
$
and therefore \eqref{shi-zhidingzuobiaoquan} is at least
\begin{equation}
	\begin{aligned}
		&\frac{m!}{(m-|S|)!}
		\prod\limits_{j\in S}\frac{x_j}{\|\textbf{x}\|_{\ell^1}}
		\left(\frac{m-|S|}{m}\right)^{m-|S|}\\
		&\qquad=
		\frac{m!}{m^m}
		\frac{(m-|S|)^{m-|S|}}{(m-|S|)!}
		\prod\limits_{j\in S}
		\frac{m x_j}{\|\textbf{x}\|_{\ell^1}}
		\geqslant
		\frac{m!}{m^m}
		\prod\limits_{j\in S}
		\frac{m x_j}{\|\textbf{x}\|_{\ell^1}}.
	\end{aligned}
	\label{shi-zhidingzuobiaoquanjie}
\end{equation}

It follows from \eqref{shi-zhidingzuobiaoquanjie} that
\begin{equation}
	\begin{aligned}
		&\sum\limits_{(i_1,\cdots,i_m)\in(J\cup\{0\})^m}
		\lambda_{i_1,\cdots,i_m}
		\textbf{y}_{i_1,\cdots,i_m}^{\alpha}\geqslant
		\sum\limits_{(i_1,\cdots,i_m)\in\mathcal I_S}
		\lambda_{i_1,\cdots,i_m}
		\textbf{y}_{i_1,\cdots,i_m}^{\alpha}
		\\&\qquad =
		\prod\limits_{j\in I}x_j^{\alpha_j}
		\prod\limits_{j\in S}
		\left(
		\frac{\|\textbf{x}\|_{\ell^1}}{m}
		\right)^{\alpha_j}
		\sum\limits_{(i_1,\cdots,i_m)\in\mathcal I_S}
		\lambda_{i_1,\cdots,i_m}
		\\
		&\qquad\geqslant
		\frac{m!}{m^m}
		\prod\limits_{j\in I}x_j^{\alpha_j}
		\prod\limits_{j\in S}
		\left(
		\frac{\|\textbf{x}\|_{\ell^1}}{m}
		\right)^{\alpha_j}
		\frac{m x_j}{\|\textbf{x}\|_{\ell^1}}
		\\
		&\qquad=
		\frac{m!}{m^m}
		\prod\limits_{j\in I}x_j^{\alpha_j}
		\prod\limits_{j\in S}
		\left(
		\frac{\|\textbf{x}\|_{\ell^1}}{m}
		\right)^{\alpha_j-1}x_j
		\\
		&\qquad\geqslant
		\frac{m!}{m^m}
		\prod\limits_{j\in I}x_j^{\alpha_j}
		\prod\limits_{j\in S}x_j^{\alpha_j}
		=
		\frac{m!}{m^m}\textbf{x}^{\alpha},
	\end{aligned}
	\label{shi-dandiaoxishuquanjie}
\end{equation}where the last inequality follows from $0<x_{j}<\frac{\|\textbf{x}\|_{\ell^{1}}}{m}, j\in S\subset J$. If
$\textbf{x}^{\alpha}=0$, \eqref{shi-dandiaoxishuquanjie} also holds. Multiplying
\eqref{shi-dandiaoxishuquanjie} by $|c_\alpha(P)|$ and summing over
$|\alpha|=m$ yields
\begin{equation}
	\frac{m!}{m^m}P^{\#}(\textbf{x})
	\leqslant
	\sum\limits_{(i_1,\cdots,i_m)\in(J\cup\{0\})^m}
	\lambda_{i_1,\cdots,i_m}
	P^{\#}(\textbf{y}_{i_1,\cdots,i_m}).
	\label{shi-jiaquanduoxiangshijie}
\end{equation}
By Lemma~\ref{yinli-zhichijishu} and \eqref{shi-xishufanshujie}, for every
$(i_1,\cdots,i_m)\in(J\cup\{0\})^m$,
$$
P^{\#}(\textbf{y}_{i_1,\cdots,i_m})
\leqslant
\binom{3m-1}{m}^{\frac{1}{2}}
\left(
\|\textbf{x}\|_Y+
\frac{\varphi(m)}{m}\|\textbf{x}\|_{\ell^1}
\right)^m
\|P\|_{\mathcal{P}^m(Y)}.
$$
Combining this estimate with \eqref{shi-quanzhongweiyi} and
\eqref{shi-jiaquanduoxiangshijie} gives
$$
P^{\#}(\textbf{x})
\leqslant
\frac{m^m}{m!}\binom{3m-1}{m}^{\frac{1}{2}}
\left(
\|\textbf{x}\|_Y+
\frac{\varphi(m)}{m}\|\textbf{x}\|_{\ell^1}
\right)^m
\|P\|_{\mathcal{P}^m(Y)},
$$
which is \eqref{shi-xishuhuaguji}.

\label{yinli-yuanziqufan}
	Let $m\in\mathbb{N}$ and let $B\in\mathcal{L}^m(Y)$ depend on
	finitely many coordinates. Then
	\begin{equation}
		\|B^{\#}\|_{\mathcal{L}^m(Y)}
		=
		\sup\limits_{\textbf{u}^{(1)},\cdots,\textbf{u}^{(m)}\in\mathcal{G}^{+}}
		B^{\#}
		\left(
		\textbf{u}^{(1)},\cdots,\textbf{u}^{(m)}
		\right).
		\label{shi-yuanziqufan}
	\end{equation}
	If $B$ is symmetric and
	$P(\textbf{z})\triangleq B(\textbf{z},\cdots,\textbf{z})$, then
	\begin{equation}
		P^{\#}(\textbf{z})
		=
		B^{\#}(\textbf{z},\cdots,\textbf{z}),
		\qquad
		\|P\|_{\mathcal{P}^m(Y)}
		\leqslant
		\|B\|_{\mathcal{L}^m(Y)},
		\label{shi-duijiaoxishu}
	\end{equation}
	and, if
	$$
	\textbf{u}^{(1)},\cdots,\textbf{u}^{(m)}\in Y,
	\qquad
	\textbf{u}^{(j)}=|\textbf{u}^{(j)}|,
	\quad 1\leqslant j\leqslant m,
	$$
	then
	\begin{equation}
		B^{\#}
		\left(
		\textbf{u}^{(1)},\cdots,\textbf{u}^{(m)}
		\right)
		\leqslant
		\frac{m^m}{m!}
		P^{\#}
		\left(
		\frac{1}{m}
		\sum\limits_{j=1}^{m}\textbf{u}^{(j)}
		\right).
		\label{shi-duichenpingjun}
	\end{equation}

\label{yinli-youxianwang}
Let $E$ be a complex normed space of dimension $d\geqslant1$, and
let $m\geqslant2$ be an integer. There is a finite set
$\mathcal{N}\subset\overline{B_E}$ such that
\begin{equation}
|\mathcal{N}|\leqslant(1+4m)^{2d},
\qquad
\|C\|_{\mathcal{L}^{m-1}(E)}
\leqslant\frac{2m}{m+1}
\max\limits_{\xi_{1} ,\cdots ,\xi_{m-1} \in \mathcal{N}} |C(\xi_{1} ,\cdots ,\xi_{m-1} )|
\label{shi-youxianwangguji}
\end{equation}
for every $C\in\mathcal{L}^{m-1}(E)$.

\label{mingti-duoxianxingguji}
For every $m\in\mathbb{N}$ and every symmetric
$B\in\mathcal{L}^m(Y)$ depending on finitely many coordinates,
\begin{equation}
\|B^{\#}\|_{\mathcal{L}^m(Y)}
\leqslant K_m\|B\|_{\mathcal{L}^m(Y)}.
\label{shi-duoxianxingguji}
\end{equation}

The argument is inspired by
\cite[Lemma~4.2 and  Theorem~4.3, pp.~59--62]{DK05}.
We first verify that
\begin{equation}
K_m\geqslant4K_{m-1},\qquad m\geqslant2.
\label{shi-changshuzengzhang}
\end{equation}
Firstly,
$$K_{2}=4\sqrt{10} \theta_{2}^{2} \geqslant 4\sqrt{10} >4K_{1},$$Then for $m\geqslant 3$, since $\left( t_{r} \right)_{r\in \mathbb{N}_{0}} ,\left( \varphi \left( n \right) \right)_{n\in \mathbb{N}}$ are increasing, we have
$$
\begin{aligned}\theta_{m}&=1+\frac{\varphi \left( m \right)}{m} t_{m^{2}-1}\geqslant 1+\frac{\varphi \left( m-1 \right)}{m} t_{\left( m-1 \right)^{2} -1}\\ &=1+\frac{\left( \theta_{m-1} -1 \right) \left( m-1 \right)}{m} =\frac{1}{m} +\frac{m-1}{m} \theta_{m-1}.\end{aligned}
$$
Hence
$$\log \theta_{m} \geqslant \log \left( \frac{1}{m} \cdot 1+\left( 1-\frac{1}{m} \right) \theta_{m-1} \right) \geqslant \frac{1}{m} \log 1+\left( 1-\frac{1}{m} \right) \log \theta_{m-1},$$
that is, $\theta_m^m\geqslant\theta_{m-1}^{m-1}$. Moreover, for $m\geqslant 3$, we have
$$
\frac{\frac{m^{m}}{m!}}{\frac{\left( m-1 \right)^{m-1}}{\left( m-1 \right) !}} =\left( 1+\frac{1}{m-1} \right)^{m-1} \geqslant 2,\frac{\binom{3m-1}{m}}{\binom{3m-4}{m-1}} =\frac{3\left( 3m-1 \right) \left( 3m-2 \right)}{2m\left( 2m-1 \right)} >1 .
$$
These inequalities prove \eqref{shi-changshuzengzhang}.

We now argue by induction on $m$. For $m=1$, put
$$
B\left( \textbf{z} \right) = \sum\limits_{i=1}^{n} B\left( e_{i} \right) z_{i},\textbf{z} =\left( z_{i} \right)_{i\in \mathbb{N}} \in Y, \omega_j\triangleq
\begin{cases}
\frac{\overline{B(e_j)}}{|B(e_j)|},&B(e_j)\neq0,\\[2pt]
1,&B(e_j)=0,
\end{cases}j=1,2,\cdots.
$$For any $\textbf{z} \in Y$, by \eqref{shi-zhihuanxiangwei} and \eqref{shi-fanshudandiao}, we have
$$\begin{aligned}\left| B^{\#}\left( \textbf{z} \right) \right|&=\left| \sum\limits_{i=1}^{n} \left| B\left( e_{i} \right) \right| z_{i} \right| =\left| \sum\limits_{i=1}^{n} \omega_{i}B\left( e_{i} \right) z_{i} \right|\\ &\leqslant \|B\| \cdot \left\| \sum\limits_{i=1}^{n} \omega_{i}z_{i}e_{i} \right\|_{Y} =\|B\| \cdot \left\| \sum\limits_{i=1}^{n} z_{i}e_{i} \right\|_{Y}\\ &\leqslant \|B\| \cdot \|\textbf{z}\|_{Y},\end{aligned}$$
and hence $\|B^{\#}\|\leqslant\|B\|$. This proves \eqref{shi-duoxianxingguji} in the case $m=1$.
Assume that $m\geqslant 2$ and that \eqref{shi-duoxianxingguji} holds with $m$ replaced by $m-1$. Fix $B$ as in the statement and set
$P(\textbf{z})\triangleq B(\textbf{z},\cdots,\textbf{z})$.
By Lemma~\ref{yinli-yuanziqufan} \eqref{shi-yuanziqufan},
it suffices to estimate
$B^{\#}(\textbf{u}^{(1)},\cdots,\textbf{u}^{(m)})$ for vectors of the form
\begin{equation}
	\textbf{u}^{(j)}
	=
	\frac{t_{r_j}}{a_{r_j}}
	\sum\limits_{k\in F_j}e_k,
	\qquad
	r_j\in\mathbb{N}_0,\quad
	F_j\subset\mathbb{N},\quad
	|F_j|=a_{r_j},
	\qquad
	1\leqslant j\leqslant m.
	\label{shi-guinayuanzi}
\end{equation}
By Proposition~\ref{mingti-jiejinyikehe}
\begin{equation}
\|\textbf{u}^{(j)}\|_Y=1,
\qquad \|\textbf{u}^{(j)}\|_{\ell^1}=t_{r_j},\qquad j=1,2,\cdots,m.
\label{shi-yuanziliangfanshu}
\end{equation}
Put $r\triangleq\max\limits_{1\leqslant j\leqslant m}r_j$.

\par\medskip\noindent\textbf{Step 1}\par\nopagebreak[4]
If $r<m^2$, set $\textbf{x}\triangleq\frac{1}{m}\sum\limits_{j=1}^{m}\textbf{u}^{(j)}$.
Then
$\textbf{x}\in\mathbb{C}^{(\mathbb{N})}\cap[0,+\infty)^{\mathbb{N}}$.
By \eqref{shi-yuanziliangfanshu}, the triangle inequality, and
monotonicity of $(t_s)_{s\in\mathbb{N}_0}$, we have
$$
\begin{aligned}
	\|\textbf{x}\|_Y
	\leqslant\frac{1}{m}\sum\limits_{j=1}^{m}\|\textbf{u}^{(j)}\|_Y=1,\qquad	\|\textbf{x}\|_{\ell^1}
	=\frac{1}{m}\sum\limits_{j=1}^{m}t_{r_j}
	\leqslant t_r\leqslant t_{m^2-1}.
\end{aligned}
$$
Applying Lemma~\ref{yinli-suijixishuhua} \eqref{shi-xishuhuaguji} to $\textbf{x}$ and using
the definition of $\theta_m$ in \eqref{shi-guinachangshu}, we obtain
$$
\begin{aligned}
	P^{\#}(\textbf{x})
	&\leqslant
	\frac{m^m}{m!}\binom{3m-1}{m}^{\frac{1}{2}}
	\left(
	\|\textbf{x}\|_Y+
	\frac{\varphi(m)}{m}\|\textbf{x}\|_{\ell^1}
	\right)^m\|P\|\leqslant
	\frac{m^m}{m!}\binom{3m-1}{m}^{\frac{1}{2}}
	\theta_m^m\|P\|.
\end{aligned}
$$
Consequently, Lemma~\ref{yinli-yuanziqufan} \eqref{shi-duichenpingjun}, \eqref{shi-duijiaoxishu},
and \eqref{shi-guinachangshu} yield
\begin{equation}
	\begin{aligned}
		B^{\#}(\textbf{u}^{(1)},\cdots,\textbf{u}^{(m)})
		&\leqslant\frac{m^m}{m!}P^{\#}(\textbf{x})\leqslant
		\left(\frac{m^m}{m!}\right)^2
		\binom{3m-1}{m}^{\frac{1}{2}}\theta_m^m\|B\|
		=K_m\|B\|.
	\end{aligned}
	\label{shi-xiaocengguji}
\end{equation}

\par\medskip\noindent\textbf{Step 2}\par\nopagebreak[4]
Suppose that $r\geqslant m^2$. Without loss of generality, assume that $r_m=r$.
Since  $r-2\geqslant2$,
the defining inequalities \eqref{shi-huanmancanshu} for $\left( t_{r} \right)_{r\in \mathbb{N}_{0}}$ give
\begin{equation}
\frac{t_r}{t_{r-2}}
=\frac{t_r}{t_{r-1}}\frac{t_{r-1}}{t_{r-2}}
\leqslant\left(1+\frac{1}{r}\right)
\left(1+\frac{1}{r-1}\right)=\frac{r+1}{r-1}.
\label{shi-liangcengbizhi}
\end{equation}
Let $J\triangleq\{j\in\{1,\cdots,m-1\}:r_j>r-2\}$.
For $j\in J$,
\begin{equation}
	\begin{aligned}
		&\frac{t_{r_j}}{t_{r-2}}\binom{a_{r_j}}{a_{r-2}}^{-1}
		\sum\limits_{\substack{D\subset F_j\\ |D|=a_{r-2}}}
		\left(\frac{t_{r-2}}{a_{r-2}}\sum\limits_{k\in D}e_k\right)\\
		&\quad=
		\frac{t_{r_j}}{a_{r-2}}\binom{a_{r_j}}{a_{r-2}}^{-1}
		\sum\limits_{k\in F_j}
		\left|\left\{D\subset F_j:|D|=a_{r-2},\ k\in D\right\}\right|e_k\\
		&\quad=
		\frac{t_{r_j}}{a_{r-2}}\binom{a_{r_j}}{a_{r-2}}^{-1}
		\binom{a_{r_j}-1}{a_{r-2}-1}\sum\limits_{k\in F_j}e_k
		=
		\frac{t_{r_j}}{a_{r_j}}\sum\limits_{k\in F_j}e_k
		=
		\textbf{u}^{(j)}.
	\end{aligned}
	\label{shi-jiangcengpingjun}
\end{equation}
For $1\leqslant j<m$, define the finite nonempty set
$$
\mathcal E_j\triangleq
\begin{cases}
\left\{\frac{t_{r-2}}{a_{r-2}}\sum\limits_{k\in D}e_k:
D\subset F_j,\ |D|=a_{r-2}\right\},&j\in J,\\[2pt]
\{\textbf{u}^{(j)}\},&j\notin J,
\end{cases}
\qquad
\Lambda\triangleq\prod\limits_{j\in J}\frac{t_{r_j}}{t_{r-2}}.
$$
Note that $$
|\mathcal E_j|
=
\begin{cases}
	\displaystyle \binom{a_{r_j}}{a_{r-2}}, & j\in J,\\[6pt]
	1, & j\notin J.
\end{cases}$$
Choose $\textbf{v}^{(j)}\in\mathcal E_j$, $1\leqslant j<m$ such that $$
B^{\#}\left(
\textbf{v}^{(1)},\cdots,\textbf{v}^{(m-1)},\textbf{u}^{(m)}
\right)
= \max\limits_{\left(\textbf{w}^{(1)},\cdots,\textbf{w}^{(m-1)}\right)
	\in\prod\limits_{j=1}^{m-1}\mathcal E_j}
B^{\#}\left(
\textbf{w}^{(1)},\cdots,\textbf{w}^{(m-1)},\textbf{u}^{(m)}
\right).
$$ Set
$\textbf{v}^{(m)}=\textbf{u}^{(m)}$. Every $\textbf{v}^{(j)}$ with $j<m$ belongs to
$\mathcal G^+\cap\bigcup\limits_{k=0}^{r-2}\mathcal G_k$.
By multilinearity and \eqref{shi-jiangcengpingjun},
\begin{equation}
	\begin{aligned}
		B^{\#}(\textbf{u}^{(1)},\cdots,\textbf{u}^{(m)})
		&=
		\left(\prod\limits_{j\in J}\frac{t_{r_j}}{t_{r-2}}\right)
		B^{\#}\left(
		\frac{1}{|\mathcal E_1|}
		\sum\limits_{\textbf{w}^{(1)}\in\mathcal E_1}\textbf{w}^{(1)},
		\cdots,
		\frac{1}{|\mathcal E_{m-1}|}
		\sum\limits_{\textbf{w}^{(m-1)}\in\mathcal E_{m-1}}\textbf{w}^{(m-1)},
		\textbf{u}^{(m)}
		\right)\\
		&=
		\frac{\Lambda}{\prod\limits_{j=1}^{m-1}|\mathcal E_j|}
		\sum\limits_{\substack{\textbf{w}^{(j)}\in\mathcal E_j\\1\leqslant j<m}}
		B^{\#}\left(
		\textbf{w}^{(1)},\cdots,\textbf{w}^{(m-1)},\textbf{u}^{(m)}
		\right)\\
		&\leqslant
		\frac{\Lambda}{\prod\limits_{j=1}^{m-1}|\mathcal E_j|}
		\left(\prod\limits_{j=1}^{m-1}|\mathcal E_j|\right)
		B^{\#}\left(
		\textbf{v}^{(1)},\cdots,\textbf{v}^{(m)}
		\right)\\
		&=
		\Lambda B^{\#}\left(
		\textbf{v}^{(1)},\cdots,\textbf{v}^{(m)}
		\right).
	\end{aligned}
	\label{shi-jiangcengguji}
\end{equation}
Monotonicity of $\left( t_{r} \right)_{r\in \mathbb{N}_{0}}$ and \eqref{shi-liangcengbizhi} imply
\begin{equation}
1\leqslant\Lambda
\leqslant\left(\frac{t_r}{t_{r-2}}\right)^{|J|}
\leqslant\left(\frac{t_r}{t_{r-2}}\right)^{m-1}
\leqslant\left(\frac{r+1}{r-1}\right)^{m-1}.
\label{shi-jiangcengxishu}
\end{equation}
Put
\begin{equation}
U\triangleq\bigcup\limits_{j=1}^{m-1}\mathrm{supp}\textbf{v}^{(j)},
\qquad |U|\leqslant(m-1)a_{r-2}.
\label{shi-guinazhichi}
\end{equation}
The space $P_UY$ has complex dimension
$|U|\geqslant1$ and carries the
norm inherited from $Y$. For $k\in F_m$, define
\begin{equation}
B_k(\textbf{z}^{(1)},\cdots,\textbf{z}^{(m-1)})
\triangleq
B\left(P_U\textbf{z}^{(1)},\cdots,
P_U\textbf{z}^{(m-1)},e_k\right).
\label{shi-gudingzuobiao}
\end{equation}
Each $B_k$ is continuous, symmetric, and depends only on the
coordinates in $U$. By \eqref{shi-touyingsuosuo}, its norm on $Y$
equals the norm of its restriction to $\left(P_UY\right)^{m-1}$. Since
$\|\textbf{v}^{(j)}\|_Y=1$ by \eqref{shi-yuanzifanshu}, the coefficient
formula \eqref{shi-zhixishuxingshi} and the induction hypothesis give
\begin{equation}
\begin{aligned}
B^{\#}(\textbf{v}^{(1)},\cdots,\textbf{v}^{(m)})
&=\frac{t_r}{a_r}\sum\limits_{k\in F_m}
B_k^{\#}(\textbf{v}^{(1)},\cdots,\textbf{v}^{(m-1)})\\
&\leqslant\frac{t_r}{a_r}\sum\limits_{k\in F_m}\|B_k^{\#}\|
\leqslant\frac{t_r}{a_r}K_{m-1}
\sum\limits_{k\in F_m}\|B_k\|.
\end{aligned}
\label{shi-diciguina}
\end{equation}

\par\medskip\noindent\textbf{Step 3}\par\nopagebreak[4]

Choose $\mathcal N\subset\overline{B_{P_UY}}$ as in
Lemma~\ref{yinli-youxianwang}. For each $k\in F_m$, choose
$\Theta(k)\in\mathcal N^{m-1}$ at which $|B_k|$ attains its maximum
on this finite set. Equation \eqref{shi-youxianwangguji} gives
\begin{equation}
\|B_k\|\leqslant\frac{2m}{m+1}|B_k(\Theta(k))|.
\label{shi-wangdianqufan}
\end{equation}
Enumerate the distinct values of $\Theta$ as
$\Theta_\nu=(\xi_\nu^{(1)},\cdots,\xi_\nu^{(m-1)})$,
$1\leqslant\nu\leqslant M$, and put
$D_\nu\triangleq\{k\in F_m:\Theta(k)=\Theta_\nu\}$.
These sets are nonempty and form a partition of $F_m$. By
\eqref{shi-guinazhichi} and \eqref{shi-youxianwangguji},
\begin{equation}
\begin{aligned}
M\leqslant|\mathcal N|^{m-1}
\leqslant(1+4m)^{2|U|(m-1)}\leqslant(1+4m)^{2(m-1)^2a_{r-2}},\qquad
\sum\limits_{\nu=1}^{M}|D_\nu|=a_r.
\end{aligned}
\label{shi-wangdianfenzu}
\end{equation}
For $k\in D_\nu$, choose
$$
\omega_k\triangleq
\begin{cases}
\frac{\overline{B_k(\Theta_\nu)}}{|B_k(\Theta_\nu)|},
&B_k(\Theta_\nu)\neq0,\\[2pt]
1,&B_k(\Theta_\nu)=0,
\end{cases}
\qquad
\textbf{w}_\nu\triangleq\sum\limits_{k\in D_\nu}\omega_ke_k.
$$
Each $\xi_\nu^{(j)}$ belongs to $P_UY$ and has norm at most $1$.
By \eqref{shi-xiangweifanshu},
$\|\textbf{w}_\nu\|_Y=\varphi(|D_\nu|)$. Hence
\eqref{shi-gudingzuobiao}, \eqref{shi-wangdianqufan}, and multilinearity give
\begin{equation}
\begin{aligned}
\sum\limits_{k\in D_\nu}\|B_k\|
&\leqslant\frac{2m}{m+1}
\sum\limits_{k\in D_\nu}|B_k(\Theta_\nu)|=\frac{2m}{m+1}
\left|B(\xi_\nu^{(1)},\cdots,\xi_\nu^{(m-1)},\textbf{w}_\nu)\right|\\& \leqslant\frac{2m}{m+1}\|B\|\varphi(|D_\nu|).
\end{aligned}
\label{shi-fenzuxiangwei}
\end{equation}
 \eqref{shi-canshuyujibenhanshu} gives $\varphi(n)\leqslant\frac{n}{t_{r-2}}$ for $n\geqslant a_{r-2}$.
For $1\leqslant n<a_{r-2}$, \eqref{shi-jiruoshoulian} and the triangle
inequality give $\varphi(n)\leqslant n<a_{r-2}$. Thus
\begin{equation}
	\varphi(n)\leqslant\frac{n}{t_{r-2}}+a_{r-2},
	\qquad n\in\mathbb N.
	\label{shi-jibenhanshuyuxiang}
\end{equation}
Summing \eqref{shi-fenzuxiangwei}  over $\nu=1,2,\cdots,M$ and using
\eqref{shi-wangdianfenzu} and \eqref{shi-jibenhanshuyuxiang}, we obtain
\begin{equation}
	\begin{aligned}
		\sum\limits_{k\in F_m}\|B_k\|
		&\leqslant\frac{2m}{m+1}\|B\|
		\sum\limits_{\nu=1}^{M}\varphi(|D_\nu|)\leqslant\frac{2m}{m+1}\|B\|
		\left(\frac{a_r}{t_{r-2}}+Ma_{r-2}\right).
	\end{aligned}
	\label{shi-fenzuzonghe}
\end{equation}
By \eqref{shi-cengjicanshu},
\begin{equation}
	a_{r-1}=2^{a_{r-2}+1},\qquad a_r=2^{\,2^{a_{r-2}+1}+1}.
	\label{shi-liangcengditui}
\end{equation}
Define 
\begin{equation}
	\varepsilon_{m,r}\triangleq
	\frac{t_ra_{r-2}}{a_r}(1+4m)^{2(m-1)^2a_{r-2}}
	=\frac{t_ra_{r-2}(1+4m)^{2(m-1)^2a_{r-2}}}
	{2^{\,2^{a_{r-2}+1}+1}}.
	\label{shi-cengjiwucha}
\end{equation}
Then \eqref{shi-wangdianfenzu} implies
\begin{equation}
	\begin{aligned}
		\frac{t_r}{a_r}\left(\frac{a_r}{t_{r-2}}+Ma_{r-2}\right)
		&=\frac{t_r}{t_{r-2}}+\frac{t_rMa_{r-2}}{a_r}\leqslant\frac{t_r}{t_{r-2}}+\varepsilon_{m,r}
		\leqslant\frac{r+1}{r-1}+\varepsilon_{m,r}.
	\end{aligned}
	\label{shi-cengjixishu}
\end{equation}
Combining \eqref{shi-jiangcengguji}, \eqref{shi-diciguina},
\eqref{shi-fenzuzonghe}, and \eqref{shi-cengjixishu}, we obtain
\begin{equation}
	\begin{aligned}
		B^{\#}(\textbf{u}^{(1)},\cdots,\textbf{u}^{(m)})
		&\leqslant\frac{2m}{m+1}\Lambda
		\frac{t_r}{a_r}\left(\frac{a_r}{t_{r-2}}+Ma_{r-2}\right)
		K_{m-1}\|B\|\\
		&\leqslant\frac{2m}{m+1}\Lambda
		\left(\frac{t_r}{t_{r-2}}+\varepsilon_{m,r}\right)K_{m-1}\|B\|\\
		&\leqslant\frac{2m}{m+1}\left(\frac{r+1}{r-1}\right)^{m-1}
		\left(\frac{r+1}{r-1}+\varepsilon_{m,r}\right)K_{m-1}\|B\|,
	\end{aligned}
	\label{shi-dacengguji}
\end{equation}
where the last inequality uses \eqref{shi-jiangcengxishu}.

\par\medskip\noindent\textbf{Step 4}\par\nopagebreak[4]

It is easy to see that
$$
r+1\leqslant 2r^2\leqslant a_{r-2},r=4,5,\cdots,\qquad1+4m\leqslant2^{m^2}, m=2,3,\cdots.
$$
Since $r\geqslant m^2$, we obtain
\begin{equation}
(1+4m)^{2(m-1)^2a_{r-2}}
\leqslant2^{2m^2(m-1)^2a_{r-2}}
\leqslant2^{2r^2a_{r-2}}
\leqslant2^{a_{r-2}^2}.
\label{shi-wangdianbijiao}
\end{equation}
$2^{a_{r-2}+1}\geqslant2a_{r-2}^2$ and
$2^{a_{r-2}^2+1}\geqslant2a_{r-2}^4\geqslant16a_{r-2}^2$.
Together with $t_r\leqslant r+1$,
\eqref{shi-cengjiwucha}, and \eqref{shi-wangdianbijiao}, this yields
\begin{equation}
\begin{aligned}
0\leqslant\varepsilon_{m,r}
&\leqslant(r+1)a_{r-2}\,2^{a_{r-2}^2-2^{a_{r-2}+1}-1}\leqslant\frac{a_{r-2}^2}{2^{a_{r-2}^2+1}}
\leqslant\frac{1}{16}.
\end{aligned}
\label{shi-wuchajiexian}
\end{equation}
It remains to compare the coefficient in \eqref{shi-dacengguji}
with $\frac{K_m}{K_{m-1}}$. If $m=2$, then $r\geqslant4$ and
$\frac{r+1}{r-1}\leqslant\frac{5}{3}$, so
\begin{equation}
\frac{2m}{m+1}\left(\frac{r+1}{r-1}\right)^{m-1}\left(\frac{r+1}{r-1}+\varepsilon_{m,r}\right)
\leqslant\frac{4}{3}\frac{5}{3}
\left(\frac{5}{3}+\frac{1}{16}\right)
=\frac{415}{108}<4.
\label{shi-erciguinabijiao}
\end{equation}
Suppose $m\geqslant3$. For $0\leqslant x<1$,
$$
e^x=\sum\limits_{j=0}^{\infty}\frac{x^j}{j!}
\leqslant\sum\limits_{j=0}^{\infty}x^j
=\frac{1}{1-x}.
$$
Together with $\log(1+x)\leqslant x$ for $x\geqslant0$ and
$r\geqslant m^2$, this gives
\begin{equation}
\begin{aligned}
\left(\frac{r+1}{r-1}\right)^{m-1}
&=\left(1+\frac{2}{r-1}\right)^{m-1}
\leqslant e^{\frac{2(m-1)}{r-1}}\leqslant e^{\frac{2}{m+1}}
\leqslant\frac{m+1}{m-1},\\
\frac{2m}{m+1}\left(\frac{r+1}{r-1}\right)^{m-1}
&\leqslant\frac{2m}{m-1}\leqslant3,
\qquad
\frac{r+1}{r-1}\leqslant\frac{m^2+1}{m^2-1}\leqslant\frac{5}{4}.
\end{aligned}
\label{shi-gaociguinabijiao}
\end{equation}
Equations \eqref{shi-wuchajiexian} and \eqref{shi-gaociguinabijiao} imply
$$
\frac{2m}{m+1}\left(\frac{r+1}{r-1}\right)^{m-1}\left(\frac{r+1}{r-1}+\varepsilon_{m,r}\right)
\leqslant3\left(\frac{5}{4}+\frac{1}{16}\right)
=\frac{63}{16}<4.
$$
Together with \eqref{shi-erciguinabijiao} and
\eqref{shi-changshuzengzhang}, this shows that the coefficient in
\eqref{shi-dacengguji} is at most $\frac{K_m}{K_{m-1}}$. Consequently,
$B^{\#}(\textbf{u}^{(1)},\cdots,\textbf{u}^{(m)})\leqslant K_m\|B\|$ when
$r\geqslant m^2$. Combining this with \eqref{shi-xiaocengguji} and
taking the supremum in \eqref{shi-yuanziqufan} proves
\eqref{shi-duoxianxingguji} in degree $m$, completing the induction.

\label{mingti-duoxiangshiguji}
For every $m\in\mathbb{N}_0$, every $P\in\mathcal{P}^m(Y)$, and every
$\textbf{z}\in Y$, one has
\begin{equation}
\sum\limits_{\substack{\alpha\in\mathbb{N}_0^{(\mathbb{N})}\\|\alpha|=m}}
|c_\alpha(P)\textbf{z}^{\alpha}|
\leqslant C_m\|P\|_{\mathcal{P}^m(Y)}\|\textbf{z}\|_Y^m.
\label{shi-fanlixishuguji}
\end{equation}
If $P$ depends on finitely many coordinates, then
\begin{equation}
\|P^{\#}\|_{\mathcal{P}^m(Y)}\leqslant C_m\|P\|_{\mathcal{P}^m(Y)}.
\label{shi-youxianxishuguji}
\end{equation}

For $m=0$, the polynomial $P$ is constant and both assertions follow
from $P^{\#}=|P|$. Let $m\geqslant1$, suppose first that $P$ depends
on finitely many coordinates.
The polarization formula in \cite[Lemma~7.13\,(1), pp.~84--85]{KM97}
gives
\begin{equation}
B(\textbf{x}^{(1)},\cdots,\textbf{x}^{(m)})
\triangleq\frac{1}{2^m m!}
\sum\limits_{\epsilon\in\{-1,1\}^m}
\left(\prod\limits_{j=1}^{m}\epsilon_j\right)
P\left(\sum\limits_{j=1}^{m}\epsilon_j\textbf{x}^{(j)}\right),P\left( \textbf{x} \right) =B\left( \textbf{x} ,\cdots ,\textbf{x} \right)
\label{shi-jihuagongshi}
\end{equation}
For $\|\textbf{x}^{(j)}\|_Y\leqslant1,j=1,2,\cdots,m$,
\eqref{shi-jihuagongshi} gives
$$
\begin{aligned}
|B(\textbf{x}^{(1)},\cdots,\textbf{x}^{(m)})|
&\leqslant\frac{\|P\|_{\mathcal{P}^m(Y)}}{2^m m!}
\sum\limits_{\epsilon\in\{-1,1\}^m}
\left\|\sum\limits_{j=1}^{m}\epsilon_j\textbf{x}^{(j)}\right\|_Y^m\leqslant\frac{m^m}{m!}\|P\|_{\mathcal{P}^m(Y)}.
\end{aligned}
$$
Hence
\begin{equation}
\|B\|_{\mathcal{L}^m(Y)}
\leqslant\frac{m^m}{m!}\|P\|_{\mathcal{P}^m(Y)}.
\label{shi-jihuafanshu}
\end{equation}
By \eqref{shi-duijiaoxishu}, \eqref{shi-duoxianxingguji}, and \eqref{shi-jihuafanshu},
$$
\begin{aligned}
\|P^{\#}\|_{\mathcal{P}^m(Y)}
&\leqslant\|B^{\#}\|_{\mathcal{L}^m(Y)}
\leqslant K_m\|B\|_{\mathcal{L}^m(Y)}\leqslant\frac{m^m}{m!}K_m\|P\|_{\mathcal{P}^m(Y)}
=C_m\|P\|_{\mathcal{P}^m(Y)}.
\end{aligned}
$$
This proves \eqref{shi-youxianxishuguji}. If $P\in\mathcal{P}^m(Y)$ , by \eqref{shi-youxianxishuguji} and $\|P\circ P_n\|\leqslant\|P\|$, it holds that
$$
\begin{aligned}
&\sum\limits_{\substack{|\alpha|=m\\
\mathrm{supp}\alpha\subset\{1,\cdots,n\}}}
|c_\alpha(P)\textbf{z}^\alpha|=
\sum\limits_{|\alpha|=m}
|c_\alpha(P\circ P_n)\textbf{z}^\alpha|=\left( P\circ P_{n} \right)^{\#} \left( \left| \textbf{z} \right| \right)
\leqslant C_m\|P\|\|\textbf{z}\|_Y^m.
\end{aligned}
$$
Letting $n\to\infty$ proves \eqref{shi-fanlixishuguji} with the same
explicit coefficient $C_m$.

The coefficients $C_m$ in \eqref{shi-duoxiangshichangshu} have at most
exponential growth. For $m\geqslant2$, $a_{m} > m^{2}-1$
gives $\kappa(m^2-1)\leqslant m-1$. By \eqref{shi-huanmancanshu},
\eqref{shi-huanmancanshujie}, and \eqref{shi-canshuyujibenhanshu},
$$
t_{m^2-1}\leqslant2t_{\kappa(m^2-1)}\leqslant2t_m
\leqslant\frac{4m}{\varphi(m)},
\qquad 1\leqslant \theta_{m} =1+\frac{\varphi \left( m \right)}{m} t_{m^{2}-1}\leqslant 1+\frac{\varphi \left( m \right)}{m} \frac{4m}{\varphi \left( m \right)} =5.
$$
Stirling's formula gives
\begin{equation}
	\begin{aligned}
		&\limsup\limits_{m\to \infty} C_{m}^{\frac{1}{m}}=\limsup\limits_{m\to \infty} \left[ \left( \frac{m^{m}}{m!} \right)^{\frac{3}{m}} \binom{3m-1}{m}^{\frac{1}{2m}} \theta_{m} \right]\\ &\  \leqslant 5\lim\limits_{m\to \infty} \left[ \left( \frac{m^{m}}{m!} \right)^{\frac{3}{m}} \binom{3m-1}{m}^{\frac{1}{2m}} \right] =\frac{15\sqrt{3}}{2} e^{3}\end{aligned}
	\label{shi-cishigenjie}
\end{equation}

\label{dingli-fanliquanshoulian}
Let $Y$ be the complex Banach sequence space in Definition~\ref{dingyi-fanlikongjian-Y}.
Then

\begin{equation}
\mathrm{dom}H(O)=O
\qquad\text{for every Reinhardt domain }O\subset Y.
\label{shi-fanliquanyushoulian}
\end{equation}
For every $f\in H(O)$ and every $\textbf{z}\in O$,
\eqref{shi-juduishoulian} and \eqref{shi-hanshubiaoshi} hold.
In particular, $Y$ is a complex Banach sequence space
satisfying  \eqref{shi-fanliquanyushoulian}
which is not isomorphic to $\ell^1$.

\label{dingli-jingdianshoulian}
One has
\begin{equation}
\mathrm{dom}H(\ell^1)=\ell^1.
\label{shi-yikeheshoulian}
\end{equation}
For $1<p\leqslant2$,
\begin{equation}
\mathrm{dom}H(\ell^p)
=
\left\{\textbf{z}\in \ell^p:
\lim\limits_{n\to\infty}
\frac{\sum\limits_{j=1}^{n}z_j^*}
{(\log(n+1))^{1-\frac{1}{p}}}=0\right\}.
\label{shi-xiaozhishushoulian}
\end{equation}
For $2<p<\infty$,
\begin{equation}
\mathrm{dom}H(\ell^p)
=
\left\{\textbf{z}\in \ell^p:
\lim\limits_{n\to\infty}
\frac{\sum\limits_{j=1}^{n}(z_j^*)^{\frac{2p}{p+2}}}
{(\log(n+1))^{\frac{p}{p+2}}}=0\right\}.
\label{shi-dazhishushoulian}
\end{equation}
Moreover,
\begin{equation}
\mathrm{dom}H(c_0)
=
\left\{\textbf{z}\in c_0:
\lim\limits_{n\to\infty}
\frac{\sum\limits_{j=1}^{n}(z_j^*)^2}{\log(n+1)}=0\right\}.
\label{shi-lingjixianshoulian}
\end{equation}

\label{yinli-chongpaixingzhi}
    For every $\textbf{z}\in c_0$ with $M(\textbf{z})<\infty$, one has
    $\textbf{z}\in X$ and
    \begin{equation}
        \|\textbf{z}\|_X\leqslant C M(\textbf{z}),
        \label{shi-chongpaiqianru}
    \end{equation}
    where $C\geqslant1$ depends only on $p$.
    Moreover, whenever $\textbf{z}\in c_0$ and $M(\textbf{z})<\infty$,
\begin{equation}
        M(\lambda\textbf{z})=|\lambda|M(\textbf{z}),\qquad
    M\bigl((z_{\pi(j)})_{j\in\mathbb{N}}\bigr)=M(\textbf{z}),\qquad
    M\bigl((\varepsilon_jz_j)_{j\in\mathbb{N}}\bigr)=M(\textbf{z}),\label{shi-chongpaiduichen}
\end{equation}
    for every $\lambda\in\mathbb{C}$, every bijection
    $\pi:\mathbb{N}\to\mathbb{N}$, and every
    $(\varepsilon_j)_{j\in\mathbb{N}}\subset\mathbb{C}$ with
    $|\varepsilon_j|=1$ for all $j\in\mathbb{N}$. If
    $\textbf{w}\in c_0$ and $|\textbf{w}|\leqslant|\textbf{z}|$, then
    $M(\textbf{w})\leqslant M(\textbf{z})$.

    Furthermore, for every $\textbf{z}\in c_0$,
    \begin{equation}
        \lim\limits_{n\to\infty}
        \frac{\left(\sum\limits_{j=1}^{n}(z_j^*)^q\right)^{\frac{1}{q}}}
        {(\log(n+1))^\sigma}=0
        \quad\Longleftrightarrow\quad
        \lim\limits_{N\to\infty}M(Q_N\textbf{z})=0.
        \label{shi-weibudengjia}
    \end{equation}
    Finally, for every $\textbf{z}\in c_0$, $N\in\mathbb{N}_0$, and
    $n\in\mathbb{N}$,
    \begin{equation}
        0\leqslant
        \left(\sum\limits_{j=1}^{n}(z_j^*)^q\right)^{\frac{1}{q}}
        -\left(\sum\limits_{j=1}^{n}
        \bigl((Q_N\textbf{z})_j^*\bigr)^q\right)^{\frac{1}{q}}
        \leqslant\|P_N\textbf{z}\|_{\ell^q}.
        \label{shi-shoubumodong}
    \end{equation}

For every $\textbf{z}\in c_0$ and $n\in\mathbb{N}$,
    \begin{equation}
        \left(\sum\limits_{j=1}^{n}(z_j^*)^q\right)^{\frac{1}{q}}
        =
        \sup\limits_{\substack{F\subset\mathbb{N}\\|F|=n}}
        \left(\sum\limits_{j\in F}|z_j|^q\right)^{\frac{1}{q}}.
        \label{shi-chongpaishangquejie}
    \end{equation}
    Hence \eqref{shi-chongpaishangquejie} yields \eqref{shi-chongpaiduichen}
    and
$
    |\textbf{w}|\leqslant|\textbf{z}|
    \Longrightarrow
    M(\textbf{w})\leqslant M(\textbf{z}).
$
    In particular,
    \begin{equation}
        M(P_N\textbf{z}),\ M(Q_N\textbf{z})
        \leqslant M(\textbf{z}).
        \label{shi-chongpaitouying}
    \end{equation}

    If $M(\textbf{z})<\infty$, then, for every $j\in\mathbb{N}$,
    $$
    j^{\frac{1}{q}}z_j^*
    \leqslant
    \left(\sum\limits_{k=1}^{j}(z_k^*)^q\right)^{\frac{1}{q}}
    \leqslant
    M(\textbf{z})(\log(j+1))^\sigma,
    $$
    and therefore
    \begin{equation}
        z_j^*\leqslant
        M(\textbf{z})
        \frac{(\log(j+1))^\sigma}{j^{\frac{1}{q}}}.
        \label{shi-chongpaidianjie}
    \end{equation}
    If $p<\infty$, then \eqref{shi-chongpaidianjie}
    and \eqref{shi-fenleizhishu} give
    $$
    \|\textbf{z}\|_X^p
    =
    \sum\limits_{j=1}^{\infty}(z_j^*)^p
    \leqslant
    M(\textbf{z})^p
    \sum\limits_{j=1}^{\infty}
    \frac{(\log(j+1))^{\sigma p}}{j^{\frac{p}{q}}}
    =
    M(\textbf{z})^p
    \sum\limits_{j=1}^{\infty}
    \frac{(\log(j+1))^{\sigma p}}{j^{1+\sigma p}}
    <\infty.
    $$
    Consequently,
    $$
    \|\textbf{z}\|_X
    \leqslant
    \left(
    \sum\limits_{j=1}^{\infty}
    \frac{(\log(j+1))^{\sigma p}}{j^{1+\sigma p}}
    \right)^{\frac{1}{p}}
    M(\textbf{z}).
    $$
    If $p=\infty$, then \eqref{shi-chongpaidianjie}
    gives
    $$
    \|\textbf{z}\|_X
    =z_1^*
    \leqslant
    (\log2)^\sigma M(\textbf{z})
    \leqslant M(\textbf{z}).
    $$
    Thus \eqref{shi-chongpaiqianru} follows.

    Let $N\in\mathbb{N}_0$ and $n\in\mathbb{N}$. For every
    $F\subset\mathbb{N}$ with $|F|=n$, Minkowski's inequality gives
    $$
    \left(\sum\limits_{j\in F}|z_j|^q\right)^{\frac{1}{q}}
    \leqslant
    \left(\sum\limits_{j\in F}|(P_N\textbf{z})_j|^q\right)^{\frac{1}{q}}
    +
    \left(\sum\limits_{j\in F}|(Q_N\textbf{z})_j|^q\right)^{\frac{1}{q}}
    $$
    and hence
    $$
    \left(\sum\limits_{j\in F}|z_j|^q\right)^{\frac{1}{q}}
    \leqslant
    \|P_N\textbf{z}\|_{\ell^q}
    +
    \left(\sum\limits_{j\in F}|(Q_N\textbf{z})_j|^q\right)^{\frac{1}{q}}.
    $$
    Taking the supremum over all such $F$ and using
    \eqref{shi-chongpaishangquejie}, we obtain
    $$
    \left(\sum\limits_{j=1}^{n}(z_j^*)^q\right)^{\frac{1}{q}}
    \leqslant
    \|P_N\textbf{z}\|_{\ell^q}
    +
    \left(\sum\limits_{j=1}^{n}
    \bigl((Q_N\textbf{z})_j^*\bigr)^q\right)^{\frac{1}{q}}.
    $$
    Moreover,
$
    |Q_N\textbf{z}|\leqslant|\textbf{z}|,
    $
    so \eqref{shi-chongpaishangquejie} gives
    $$
    \left(\sum\limits_{j=1}^{n}
    \bigl((Q_N\textbf{z})_j^*\bigr)^q\right)^{\frac{1}{q}}
    \leqslant
    \left(\sum\limits_{j=1}^{n}(z_j^*)^q\right)^{\frac{1}{q}}.
    $$
    Thus \eqref{shi-shoubumodong} follows.

    Suppose
$
    \lim\limits_{n\to\infty}
    \frac{\left(\sum\limits_{j=1}^{n}(z_j^*)^q\right)^{\frac{1}{q}}}
    {(\log(n+1))^\sigma}
    =0.
$
    For every $\varepsilon>0$, there exists $n_0\geqslant2,n_0\in \mathbb{N}$ such that
    $$
    \frac{\left(\sum\limits_{j=1}^{n}(z_j^*)^q\right)^{\frac{1}{q}}}
    {(\log(n+1))^\sigma}
    \leqslant\varepsilon,
    \qquad n\geqslant n_0.
    $$
    Since $|Q_N\textbf{z}|\leqslant|\textbf{z}|$,
    \eqref{shi-chongpaishangquejie} gives
    $$
    \frac{\left(\sum\limits_{j=1}^{n}
        \bigl((Q_N\textbf{z})_j^*\bigr)^q\right)^{\frac{1}{q}}}
    {(\log(n+1))^\sigma}
    \leqslant\varepsilon,
    \qquad n\geqslant n_0.
    $$
    For $1\leqslant n<n_0$,
    $$
    \frac{\left(\sum\limits_{j=1}^{n}
        \bigl((Q_N\textbf{z})_j^*\bigr)^q\right)^{\frac{1}{q}}}
    {(\log(n+1))^\sigma}
    \leqslant
    \frac{n^{\frac{1}{q}}}{(\log(n+1))^\sigma}
    \|Q_N\textbf{z}\|_{\ell^\infty}
    \leqslant
    \frac{n_0^{\frac{1}{q}}}{(\log2)^\sigma}
    \|Q_N\textbf{z}\|_{\ell^\infty}.
    $$
    Therefore
    $$
    M(Q_N\textbf{z})
    \leqslant
    \max\left\{
    \varepsilon,
    \frac{n_0^{\frac{1}{q}}}{(\log2)^\sigma}
    \|Q_N\textbf{z}\|_{\ell^\infty}
    \right\}.
    $$
    Since $\textbf{z}\in c_0$,
$
    \lim\limits_{N\to\infty}
    \|Q_N\textbf{z}\|_{\ell^\infty}=0,
$
    and hence
$
    \limsup\limits_{N\to\infty}M(Q_N\textbf{z})
    \leqslant\varepsilon.
$
    Letting $\varepsilon\to0$ gives
$
    \lim\limits_{N\to\infty}M(Q_N\textbf{z})=0.
$

Conversely, \eqref{shi-shoubumodong} gives, for every
    $N\in\mathbb{N}_0$ and $n\in\mathbb{N}$,
    $$
    \frac{\left(\sum\limits_{j=1}^{n}(z_j^*)^q\right)^{\frac{1}{q}}}
    {(\log(n+1))^\sigma}
    \leqslant
    \frac{\|P_N\textbf{z}\|_{\ell^q}}{(\log(n+1))^\sigma}
    +
    \frac{\left(\sum\limits_{j=1}^{n}
        \bigl((Q_N\textbf{z})_j^*\bigr)^q\right)^{\frac{1}{q}}}
    {(\log(n+1))^\sigma}.
    $$
    By \eqref{shi-chongpaoliang},
    $$
    \frac{\left(\sum\limits_{j=1}^{n}(z_j^*)^q\right)^{\frac{1}{q}}}
    {(\log(n+1))^\sigma}
    \leqslant
    \frac{\|P_N\textbf{z}\|_{\ell^q}}{(\log(n+1))^\sigma}
    +
    M(Q_N\textbf{z}).
    $$
Therefore
    $$
    \limsup\limits_{n\to\infty}
    \frac{\left(\sum\limits_{j=1}^{n}(z_j^*)^q\right)^{\frac{1}{q}}}
    {(\log(n+1))^\sigma}
    \leqslant M(Q_N\textbf{z}).
    $$
    Thus
$
    \lim\limits_{N\to\infty}M(Q_N\textbf{z})=0
$
    implies
    $$
    \lim\limits_{n\to\infty}
    \frac{\left(\sum\limits_{j=1}^{n}(z_j^*)^q\right)^{\frac{1}{q}}}
    {(\log(n+1))^\sigma}=0.
    $$
    This proves \eqref{shi-weibudengjia}.

\label{yinli-fenkuaiqiuhe}
For $X,p,q,\sigma$ as in \eqref{shi-fenleizhishu}, let
$C_0\geqslant1$ satisfy
\begin{equation}
\begin{aligned}
2^{\frac{1}{q}}(\log2)^\sigma&\leqslant C_0,
& e^2 2^{4\sigma+\frac{1}{p}}&\leqslant C_0,\\
u^\sigma(1+u)^{1-\frac{1}{q}}2^{-\frac{\sigma u}{2}}
&\leqslant C_0\quad(u\geqslant0),
&2^\sigma\max\left\{1,
\frac{2^{-\frac{\sigma}{2}}}{1-2^{-\frac{\sigma}{2}}}\right\}
&\leqslant C_0.
\end{aligned}
\label{shi-fuzhuchangshu}
\end{equation}
Let $1\leqslant k_0\leqslant K$ be integers and let
$\omega_{k_0},\cdots,\omega_K\geqslant0$ satisfy
\begin{equation}
\left(\sum\limits_{k=k_0}^{L}\omega_k^q\right)^{\frac{1}{q}}
\leqslant C_0L^\sigma,
\qquad k_0\leqslant L\leqslant K.
\label{shi-kuaibufenhe}
\end{equation}
Then, for every $d\in\mathbb{N}$ and $k_0\leqslant L\leqslant K$,
\begin{equation}
d^{\frac{d}{p}}
\sum\limits_{\substack{\beta_{k_0},\cdots,\beta_L\in\mathbb{N}_0\\
\beta_{k_0}+\cdots+\beta_L=d}}
\prod\limits_{k=k_0}^{L}\frac{\omega_k^{\beta_k}}{(\beta_k!)^{\frac{1}{q}}}
\leqslant(3C_0)^d\left(\frac{L}{d}\right)^{\sigma d}
\left(1+\frac{L}{d}\right)^{(1-\frac{1}{q})d}.
\label{shi-duocishuqiuhe}
\end{equation}
Moreover, for every $d\in\mathbb{N}$,
\begin{equation}
d^\sigma\sum\limits_{L=1}^{\infty}2^{-\sigma L}
\left(\frac{L}{d}\right)^{\sigma d}
\left(1+\frac{L}{d}\right)^{(1-\frac{1}{q})d}
\leqslant C_0^{2d}.
\label{shi-zhishishuaijian}
\end{equation}

Fix $d\in\mathbb{N}$ and $k_0\leqslant L\leqslant K$. By \eqref{shi-fenleizhishu}, $1\leqslant q\leqslant2$ and $\frac{1}{p}-\frac{1}{q}=-\sigma<0$. We have
    \begin{equation}
        \#\left\{
        (\beta_{k_0},\cdots,\beta_L)\in\mathbb{N}_0^{L-k_0+1}:
        \sum\limits_{k=k_0}^{L}\beta_k=d
        \right\}
        =\binom{L-k_0+d}{d}\leqslant\binom{L+d}{d}.
        \label{shi-duocishujishu}
    \end{equation}
    By \eqref{shi-duocishujishu}, H\"older's inequality, and the multinomial theorem,
    \begin{equation}
        \begin{aligned}
            \sum\limits_{\substack{\beta_{k_0},\cdots,\beta_L\in\mathbb{N}_0\\
                    \beta_{k_0}+\cdots+\beta_L=d}}
            \prod\limits_{k=k_0}^{L}\frac{\omega_k^{\beta_k}}{(\beta_k!)^{\frac{1}{q}}}
            &\quad\leqslant
            \binom{L+d}{d}^{1-\frac{1}{q}}
            \left(
            \sum\limits_{\substack{\beta_{k_0},\cdots,\beta_L\in\mathbb{N}_0\\
                    \beta_{k_0}+\cdots+\beta_L=d}}
            \prod\limits_{k=k_0}^{L}\frac{\omega_k^{q\beta_k}}{\beta_k!}
            \right)^{\frac{1}{q}}\\
            &\quad=
            \binom{L+d}{d}^{1-\frac{1}{q}}
            \frac{\left(\sum\limits_{k=k_0}^{L}\omega_k^q\right)^{\frac{d}{q}}}
            {(d!)^{\frac{1}{q}}}.
        \end{aligned}
        \label{shi-duochongheguji}
    \end{equation}
    By \begin{equation}
  \begin{aligned}d!&=e^{\sum\limits_{k=1}^{d} \log k}\geqslant e^{\sum\limits_{k=2}^{d} \int\limits_{k-1}^{k} \log x\mathrm{d} x}=e^{d\log d-d+1}\geqslant e^{d\log d-\log 3\cdot d}=\left( \frac{d}{3} \right)^{d} ,\end{aligned}
    \end{equation}we have
    \begin{equation}
\binom{L+d}{d}\leqslant\frac{(L+d)^d}{d!}
\leqslant\left(3\left(1+\frac{L}{d}\right)\right)^d.
        \
        \label{shi-fenkuaijicheng}
    \end{equation}
    By \eqref{shi-duochongheguji}, \eqref{shi-fenkuaijicheng}, \eqref{shi-kuaibufenhe}, and \eqref{shi-fenleizhishu},
    $$
    \begin{aligned}
        &d^{\frac{d}{p}}
        \sum\limits_{\substack{\beta_{k_0},\cdots,\beta_L\in\mathbb{N}_0\\
                \beta_{k_0}+\cdots+\beta_L=d}}
        \prod\limits_{k=k_0}^{L}\frac{\omega_k^{\beta_k}}{(\beta_k!)^{\frac{1}{q}}}\leqslant
        d^{\frac{d}{p}}
        \left(3\left(1+\frac{L}{d}\right)\right)^{(1-\frac{1}{q})d}
        (C_0L^\sigma)^d\left(\frac{3}{d}\right)^{\frac{d}{q}}\\
        &\quad=
        (3C_0)^dL^{\sigma d}d^{(\frac{1}{p}-\frac{1}{q})d}
        \left(1+\frac{L}{d}\right)^{(1-\frac{1}{q})d}
        =
        (3C_0)^d\left(\frac{L}{d}\right)^{\sigma d}
        \left(1+\frac{L}{d}\right)^{(1-\frac{1}{q})d}.
    \end{aligned}
    $$
    This proves \eqref{shi-duocishuqiuhe}.

    Finally, $d\leqslant2^d$ and \eqref{shi-fuzhuchangshu} give
    $$
    \begin{aligned}
        &d^\sigma\sum\limits_{L=1}^{\infty}
        2^{-\sigma L}
        \left(\frac{L}{d}\right)^{\sigma d}
        \left(1+\frac{L}{d}\right)^{(1-\frac{1}{q})d}=
        d^\sigma\sum\limits_{L=1}^{\infty}2^{-\frac{\sigma L}{2}}
        \left[
        \left(\frac{L}{d}\right)^\sigma
        \left(1+\frac{L}{d}\right)^{1-\frac{1}{q}}
        2^{-\frac{\sigma L}{2d}}
        \right]^d\\
        &\quad\leqslant
        (2^\sigma C_0)^d
        \sum\limits_{L=1}^{\infty}2^{-\frac{\sigma L}{2}}=
        (2^\sigma C_0)^d
        \frac{2^{-\frac{\sigma}{2}}}{1-2^{-\frac{\sigma}{2}}}
\leqslant
        C_0^d\left[
        2^\sigma\max\left\{1,
        \frac{2^{-\frac{\sigma}{2}}}{1-2^{-\frac{\sigma}{2}}}
        \right\}
        \right]^d
        \leqslant C_0^{2d}.
    \end{aligned}
    $$
    This proves \eqref{shi-zhishishuaijian}.

\label{yinli-chongpaixishuguji}
	For $X,p,q,\sigma$ as in \eqref{shi-fenleizhishu}, there exists
	a constant $C\geqslant1$, depending only on $p$, such that, for every
	$m\in\mathbb{N}$, every $G\in\mathcal{P}^m(X)$, and every
	$\textbf{z}\in c_0$ with $M(\textbf{z})<\infty$,
	\begin{equation}
		\sum\limits_{\substack{\alpha\in\mathbb{N}_0^{(\mathbb{N})}\\
				|\alpha|=m}}
		|c_\alpha(G)\textbf{z}^\alpha|
		\leqslant
		C^m M(\textbf{z})^m\|G\|.
		\label{shi-chongpaixishuguji}
	\end{equation}

Fix $p$ and choose $C_0\geqslant1$, depending only on $p$, such that \eqref{shi-fuzhuchangshu} holds and \eqref{shi-chongpaiqianru} holds with $C=C_0$. We first assume $G=G\circ P_n$. 

    \par\medskip\noindent\textbf{Step 1}\par\nopagebreak[4]
For $m\geqslant2$ and $\emptyset\neq A\subset\{\alpha\in\mathbb{N}_0^{(\mathbb{N})}:|\alpha|=m,\ \mathrm{supp}\alpha\subset\{1,\cdots,n\}\}$, put
    \begin{equation}
        A^-\triangleq\{\alpha-e_{\max\mathrm{supp}\alpha}:\alpha\in A\}.
        \label{shi-shanjianzhiji}
    \end{equation}
    By \eqref{shi-duoxiangshifanshu} and \eqref{shi-shouweisuosuo}, $\|G\|=\sup\limits_{\|\textbf{u}\|_{\ell^p}\leqslant1}|G(\sum\limits_{j=1}^{n}u_je_j)|$, where $\textbf{u}\in\mathbb{C}^n$. Moreover,
    \begin{equation}
        \begin{gathered}
            \alpha=\sum\limits_{\nu=1}^{m}e_{j_\nu}
            \quad\Longrightarrow\quad
            \alpha-e_{\max\mathrm{supp}\alpha}=\sum\limits_{\nu=1}^{m-1}e_{j_\nu},
            \qquad 1\leqslant j_1\leqslant\cdots\leqslant j_m\leqslant n,\\
            em\max\left\{e^{\frac{m-1}{p}},2^{\frac{m-1}{2}}\right\}
            \leqslant me^m\leqslant e^{2m}.
        \end{gathered}
        \label{shi-zhijiduiying}
    \end{equation}
    Thus \cite[Theorem~3.2]{BDS19} and \eqref{shi-zhijiduiying} give
    \begin{equation}
        \sum\limits_{\alpha\in A}|c_\alpha(G)\textbf{u}^\alpha|
        \leqslant e^{2m}|A^-|^\sigma\|\textbf{u}\|_X^m\|G\|,
        \qquad \textbf{u}\in X.
        \label{shi-zhijixishuguji}
    \end{equation}

    Take $\pi\in S_n$ with $|z_{\pi(1)}|\geqslant\cdots\geqslant|z_{\pi(n)}|$ and define
    \begin{equation}
        \begin{aligned}
            \varepsilon_j&\triangleq
            \begin{cases}
                \displaystyle\frac{\overline{z_{\pi(j)}}}{|z_{\pi(j)}|},&z_{\pi(j)}\neq0,\\
                1,&z_{\pi(j)}=0,
            \end{cases}
            \qquad 1\leqslant j\leqslant n,\\
            T\textbf{x}&\triangleq\sum\limits_{j=1}^{n}\varepsilon_jx_{\pi(j)}e_j+Q_n\textbf{x},
            \qquad \textbf{x}\in X.
        \end{aligned}
        \label{shi-chongpaibianhuan}
    \end{equation}
    Then \eqref{shi-chongpaibianhuan} yields
    \begin{equation}
        \begin{gathered}
            T^{-1}\textbf{x}=\sum\limits_{j=1}^{n}\overline{\varepsilon_j}x_je_{\pi(j)}+Q_n\textbf{x},
            \qquad \|T\textbf{x}\|_X=\|\textbf{x}\|_X,\\
            TP_n=P_nT,
            \qquad TP_n\textbf{z}=\sum\limits_{j=1}^{n}|z_{\pi(j)}|e_j=(P_n\textbf{z})^*.
        \end{gathered}
        \label{shi-chongpaidengju}
    \end{equation}
    By \eqref{shi-chongpaidengju}, \eqref{shi-youxianzhankai}, \eqref{shi-chongpaiduichen}, and \eqref{shi-chongpaitouying},
    \begin{equation}
        \begin{gathered}
            \|G\circ T^{-1}\|=\|G\|,
            \qquad M(TP_n\textbf{z})=M(P_n\textbf{z})\leqslant M(\textbf{z}),\\
            \sum\limits_{|\alpha|=m}|c_\alpha(G)\textbf{z}^\alpha|
            =\sum\limits_{|\alpha|=m}|c_\alpha(G\circ T^{-1})(TP_n\textbf{z})^\alpha|.
        \end{gathered}
        \label{shi-xishuhebudong}
    \end{equation}
For proving \eqref{shi-chongpaixishuguji}, the cases
$G=0$ and $P_n\textbf{z}=\textbf{0}$ are immediate.
By \eqref{shi-xishuhebudong} and homogeneity,
it therefore suffices to assume
    \begin{equation}
        \|G\|=M(\textbf{z})=1,
        \qquad z_1\geqslant\cdots\geqslant z_n\geqslant0,
        \qquad z_j=0\quad(j>n).
        \label{shi-jingdianguifan}
    \end{equation}
    For $m=1$, \eqref{shi-youxianzhankai} and \eqref{shi-chongpaiqianru} give
    \begin{equation}
        \sum\limits_{j=1}^{n}|c_{e_j}(G)|z_j
        =\sup\limits_{|w_j|\leqslant z_j\ (j\in\mathbb{N})}|G(\textbf{w})|
        \leqslant\|G\|\|\textbf{z}\|_X\leqslant C_0.
        \label{shi-yicixishuguji}
    \end{equation}

    \par\medskip\noindent\textbf{Step 2}\par\nopagebreak[4]
Henceforth $m\geqslant2$. Put
    \begin{gather}
        k_0\triangleq\left\lceil\frac{\log m}{\log2}\right\rceil,
        \quad I_0\triangleq\{1,\cdots,2^{k_0}-1\},
        \quad I_k\triangleq\{2^k,\cdots,2^{k+1}-1\}\quad(k\geqslant k_0).
        \notag\\
        1\leqslant|I_0|<2m,
        \qquad |I_k|=2^k\geqslant m\quad(k\geqslant k_0).
        \label{shi-shuangjinfenkuai}
    \end{gather}
    Increasing $n$ if necessary, take $n=2^{K+1}-1$ with $K\geqslant k_0$. By \eqref{shi-fenleizhishu} and \eqref{shi-jingdianguifan},
    \begin{equation}
        \omega_k\triangleq2^{\sigma k}\|P_{I_k}\textbf{z}\|_X
        \leqslant2^{k(\sigma+\frac{1}{p})}z_{2^k}
        =2^{\frac{k}{q}}z_{2^k},
        \qquad k_0\leqslant k\leqslant K.
        \label{shi-kuaiquanzhong}
    \end{equation}
    For $k_0\leqslant L\leqslant K$, \eqref{shi-jingdianguifan}, \eqref{shi-kuaiquanzhong} and \eqref{shi-chongpaoliang} yield
    \begin{equation}
        \begin{aligned}
            \sum\limits_{k=k_0}^{L}\omega_k^q
            &\leqslant\sum\limits_{k=k_0}^{L}2^kz_{2^k}^q
            \leqslant2\sum\limits_{k=k_0}^{L}\sum\limits_{j=2^{k-1}}^{2^k-1}z_j^q\\
            &=2\sum\limits_{j=2^{k_0-1}}^{2^L-1}z_j^q
            \leqslant2\sum\limits_{j=1}^{2^L-1}z_j^q
            \leqslant2(L\log2)^{\sigma q}.
        \end{aligned}
        \label{shi-quanzhongbufenhe}
    \end{equation}
    By \eqref{shi-chongpaiqianru}, \eqref{shi-quanzhongbufenhe}, and \eqref{shi-fuzhuchangshu},
    \begin{equation}
        \|P_{I_0}\textbf{z}\|_X\leqslant C_0,
        \qquad
        \left(\sum\limits_{k=k_0}^{L}\omega_k^q\right)^{\frac{1}{q}}
        \leqslant2^{\frac{1}{q}}(\log2)^\sigma L^\sigma
        \leqslant C_0L^\sigma.
        \label{shi-kuaitongyijie}
    \end{equation}

    \par\medskip\noindent\textbf{Step 3}\par\nopagebreak[4]
For $\beta=(\beta_{k_0},\cdots,\beta_K)\in\mathbb{N}_0^{K-k_0+1}$, write $|\beta|\triangleq\sum\limits_{k=k_0}^{K}\beta_k$. For $h\in\mathbb{N}_0$ with $h+|\beta|=m$, set
    \begin{equation}
        A_{h,\beta}\triangleq\left\{\alpha\in\mathbb{N}_0^{(\mathbb{N})}:
        \begin{gathered}
            |\alpha|=m,\quad\mathrm{supp}\alpha\subset\{1,\cdots,n\},\\
            \sum\limits_{j\in I_0}\alpha_j=h,\quad
            \sum\limits_{j\in I_k}\alpha_j=\beta_k\quad(k_0\leqslant k\leqslant K)
        \end{gathered}\right\}.
        \label{shi-fenkuaizhiji}
    \end{equation}
    By \eqref{shi-youxianzhankai} and \eqref{shi-fenkuaizhiji},
    \begin{equation}
        \sum\limits_{|\alpha|=m}|c_\alpha(G)\textbf{z}^\alpha|
        =\sum\limits_{h+|\beta|=m}\sum\limits_{\alpha\in A_{h,\beta}}
        |c_\alpha(G)\textbf{z}^\alpha|.
        \label{shi-xishuhefenjie}
    \end{equation}
    For $h<m$, put
    $$
        d\triangleq m-h=|\beta|\geqslant1,
        \qquad L\triangleq\max\{k:\beta_k>0\},
        \qquad t\triangleq\max I_L.
    $$
    For $\eta\in\mathbb{N}_0^{(\mathbb{N})}$, \eqref{shi-shanjianzhiji} and \eqref{shi-fenkuaizhiji} give
    \begin{equation}
        \begin{gathered}
            \alpha\in A_{h,\beta},\quad j=\max\mathrm{supp}\alpha
            \quad\Longrightarrow\quad j\in I_L,\quad\alpha-e_j+e_t\in A_{h,\beta},\\
            \eta+e_t\in A_{h,\beta}
            \quad\Longrightarrow\quad\max\mathrm{supp}(\eta+e_t)=t,\quad
            \eta=(\eta+e_t)-e_t\in A_{h,\beta}^-.
        \end{gathered}
        \label{shi-zuidazhibiao}
    \end{equation}
    Consequently, \eqref{shi-zuidazhibiao} gives
    \begin{equation}
        \begin{aligned}
            \eta\in A_{h,\beta}^-
            &\Longleftrightarrow\eta+e_t\in A_{h,\beta}\\
            &\Longleftrightarrow
            \begin{cases}
                \mathrm{supp}\eta\subset\{1,\cdots,t\},\\
                \sum\limits_{j\in I_0}\eta_j=h,\quad
                \sum\limits_{j\in I_L}\eta_j=\beta_L-1,\\
                \sum\limits_{j\in I_k}\eta_j=\beta_k\quad(k_0\leqslant k<L).
            \end{cases}
        \end{aligned}
        \label{shi-shanjianjikehua}
    \end{equation}
   By \eqref{shi-shanjianjikehua}, the coordinates of $\eta$ in the different blocks may be chosen independently. The numbers of nonnegative integer solutions on $I_0$, $I_k$ $(k_0\leqslant k<L)$, and $I_L$ are respectively
   $$
   \binom{|I_0|+h-1}{h},\qquad
   \binom{2^k+\beta_k-1}{\beta_k},\qquad
   \binom{2^L+\beta_L-2}{\beta_L-1}.
   $$
   Therefore,
   \begin{equation}
   	|A_{h,\beta}^-|
   	=\binom{|I_0|+h-1}{h}
   	\binom{2^L+\beta_L-2}{\beta_L-1}
   	\prod\limits_{k=k_0}^{L-1}
   	\binom{2^k+\beta_k-1}{\beta_k}.
   	\label{shi-shanjianjijishu}
   \end{equation}
    By \eqref{shi-shuangjinfenkuai},
    \begin{equation}
        \begin{aligned}
            \binom{|I_0|+h-1}{h}
            &\leqslant2^{|I_0|+h-1}\leqslant2^{3m},
            &&0\leqslant h\leqslant m,\\
            \binom{2^k+v-1}{v}
            &=\frac{\prod\limits_{\nu=0}^{v-1}(2^k+\nu)}{v!}
            \leqslant\frac{2^{(k+1)v}}{v!},
            &&k\geqslant k_0,\quad 0\leqslant v\leqslant m.
        \end{aligned}
        \label{shi-kuaizuhejie}
    \end{equation}
    Combining \eqref{shi-shanjianjijishu} and \eqref{shi-kuaizuhejie}, we obtain
    \begin{equation}
        \begin{aligned}
            |A_{h,\beta}^-|
            &\leqslant2^{3m}\frac{2^{(L+1)(\beta_L-1)}}{(\beta_L-1)!}
            \prod\limits_{k=k_0}^{L-1}\frac{2^{(k+1)\beta_k}}{\beta_k!}\\
            &=2^{3m+d-1}\frac{\beta_L}{2^L}
            \prod\limits_{k=k_0}^{L}\frac{2^{k\beta_k}}{\beta_k!}
            \leqslant2^{4m}\frac{\beta_L}{2^L}
            \prod\limits_{k=k_0}^{L}\frac{2^{k\beta_k}}{\beta_k!}.
        \end{aligned}
        \label{shi-shanjianjishangjie}
    \end{equation}

    \par\medskip\noindent\textbf{Step 4}\par\nopagebreak[4]
By \eqref{shi-fenkuaizhiji},
    \begin{equation}
        \|P_{I_0}\textbf{z}\|_X^h
        \prod\limits_{k=k_0}^{K}\|P_{I_k}\textbf{z}\|_X^{\beta_k}=0
        \quad\Longrightarrow\quad
        \sum\limits_{\alpha\in A_{h,\beta}}|c_\alpha(G)\textbf{z}^\alpha|=0.
        \label{shi-lingkuaichuli}
    \end{equation}
    Otherwise, define $\textbf{u}$ by
    \begin{equation}
        \begin{aligned}
            P_{I_0}\textbf{u}
            &\triangleq\left(\frac{h}{m}\right)^{\frac{1}{p}}
            \frac{P_{I_0}\textbf{z}}{\|P_{I_0}\textbf{z}\|_X}
            &&\text{if }h>0,\\
            P_{I_k}\textbf{u}
            &\triangleq\left(\frac{\beta_k}{m}\right)^{\frac{1}{p}}
            \frac{P_{I_k}\textbf{z}}{\|P_{I_k}\textbf{z}\|_X}
            &&\text{if }\beta_k>0,\quad k_0\leqslant k\leqslant K,
        \end{aligned}
        \label{shi-kuaiguifanhua}
    \end{equation}
    and set all remaining coordinates of $\textbf{u}$ equal to zero. By \eqref{shi-kuaiguifanhua},
    \begin{equation}
        \|\textbf{u}\|_X^p=\frac{h}{m}+\sum\limits_{k=k_0}^{K}\frac{\beta_k}{m}=1
        \quad(p<\infty),\qquad
        \|\textbf{u}\|_X=1\quad(p=\infty).
        \label{shi-kuaixiangliangfanshu}
    \end{equation}
    For $\alpha\in A_{h,\beta}$, \eqref{shi-fenkuaizhiji} and \eqref{shi-kuaiguifanhua} give
    \begin{equation}
        \textbf{z}^\alpha
        =\frac{m^{\frac{m}{p}}}{h^{\frac{h}{p}}}\|P_{I_0}\textbf{z}\|_X^h
        \prod\limits_{k=k_0}^{K}\frac{\|P_{I_k}\textbf{z}\|_X^{\beta_k}}{\beta_k^{\frac{\beta_k}{p}}}
        \,\textbf{u}^\alpha.
        \label{shi-kuaidanxiangshi}
    \end{equation}
    By \eqref{shi-zhijixishuguji}, \eqref{shi-kuaixiangliangfanshu}, and \eqref{shi-kuaidanxiangshi},
    \begin{equation}
        \begin{aligned}
            \sum\limits_{\alpha\in A_{h,\beta}}|c_\alpha(G)\textbf{z}^\alpha|
            &\leqslant e^{2m}|A_{h,\beta}^-|^\sigma
            \frac{m^{\frac{m}{p}}}{h^{\frac{h}{p}}}\|P_{I_0}\textbf{z}\|_X^h
            \prod\limits_{k=k_0}^{K}\frac{\|P_{I_k}\textbf{z}\|_X^{\beta_k}}{\beta_k^{\frac{\beta_k}{p}}}.
        \end{aligned}
        \label{shi-dankuaixishuguji}
    \end{equation}
    Since $h+d=m$, the identity $\max\limits_{0\leqslant u\leqslant1}\{-u\log u-(1-u)\log(1-u)\}=\log2$ gives
    \begin{equation}
        \frac{m^m}{h^hd^d}
        =e^{m\left(-\frac{h}{m}\log\frac{h}{m}-\frac{d}{m}\log\frac{d}{m}\right)}
        \leqslant2^m.
        \label{shi-eryuanshang}
    \end{equation}
    Also, $v!\leqslant v^v$ and \eqref{shi-fenleizhishu} give
    \begin{equation}
        \frac{1}{(v!)^\sigma v^{\frac{v}{p}}}
        \leqslant\frac{1}{(v!)^{\sigma+\frac{1}{p}}}
        =\frac{1}{(v!)^{\frac{1}{q}}},
        \qquad v\in\mathbb{N}_0.
        \label{shi-jichenghebing}
    \end{equation}
    Substitute \eqref{shi-shanjianjishangjie} and \eqref{shi-kuaiquanzhong} into \eqref{shi-dankuaixishuguji}. Using $\beta_L\leqslant d$, \eqref{shi-eryuanshang}, and \eqref{shi-jichenghebing}, we obtain
    \begin{equation}
        \begin{aligned}
            \sum\limits_{\alpha\in A_{h,\beta}}|c_\alpha(G)\textbf{z}^\alpha|
            &\leqslant e^{2m}2^{4\sigma m}\beta_L^\sigma2^{-\sigma L}
            \|P_{I_0}\textbf{z}\|_X^h
            \frac{m^{\frac{m}{p}}}{h^{\frac{h}{p}}}
            \prod\limits_{k=k_0}^{L}
            \frac{\omega_k^{\beta_k}}{(\beta_k!)^\sigma\beta_k^{\frac{\beta_k}{p}}}\\
            &\leqslant\left(e^2 2^{4\sigma+\frac{1}{p}}\right)^m
            d^\sigma2^{-\sigma L}\|P_{I_0}\textbf{z}\|_X^{m-d}d^{\frac{d}{p}}
            \prod\limits_{k=k_0}^{L}\frac{\omega_k^{\beta_k}}{(\beta_k!)^{\frac{1}{q}}}\\
            &\leqslant C_0^m d^\sigma2^{-\sigma L}
            \|P_{I_0}\textbf{z}\|_X^{m-d}d^{\frac{d}{p}}
            \prod\limits_{k=k_0}^{L}\frac{\omega_k^{\beta_k}}{(\beta_k!)^{\frac{1}{q}}},
        \end{aligned}
        \label{shi-kuaishuaijianguji}
    \end{equation}
    where the last inequality follows from \eqref{shi-fuzhuchangshu}. By \eqref{shi-lingkuaichuli}, \eqref{shi-kuaishuaijianguji} also holds if $h>0$ and $\| P_{I_0}\textbf z\|_X=0$, or if $\beta_k>0$ and $\| P_{I_k}\textbf z\|_X=0$ for some $k_0\leqslant k\leqslant L$.

    \par\medskip\noindent\textbf{Step 5}\par\nopagebreak[4]
By \eqref{shi-kuaitongyijie}, Lemma~\ref{yinli-fenkuaiqiuhe} applies to $(\omega_k)_{k=k_0}^{K}$. For $1\leqslant d\leqslant m$, \eqref{shi-kuaishuaijianguji} gives
    \begin{equation}
        \begin{aligned}
            \sum\limits_{|\beta|=d}\sum\limits_{\alpha\in A_{m-d,\beta}}
            |c_\alpha(G)\textbf{z}^\alpha|
            &=\sum\limits_{L=k_0}^{K}
            \sum\limits_{\substack{|\beta|=d\\\max\{k:\beta_k>0\}=L}}
            \sum\limits_{\alpha\in A_{m-d,\beta}}|c_\alpha(G)\textbf{z}^\alpha|\\
            &\leqslant C_0^m\|P_{I_0}\textbf{z}\|_X^{m-d}d^\sigma
            \sum\limits_{L=k_0}^{K}2^{-\sigma L}d^{\frac{d}{p}}
            \sum\limits_{\substack{\beta_{k_0},\cdots,\beta_L\in\mathbb{N}_0\\
                    \beta_{k_0}+\cdots+\beta_L=d}}
            \prod\limits_{k=k_0}^{L}\frac{\omega_k^{\beta_k}}{(\beta_k!)^{\frac{1}{q}}}\\
            &\leqslant C_0^m\|P_{I_0}\textbf{z}\|_X^{m-d}(3C_0)^d d^\sigma
            \sum\limits_{L=k_0}^{K}2^{-\sigma L}
            \left(\frac{L}{d}\right)^{\sigma d}
            \left(1+\frac{L}{d}\right)^{(1-\frac{1}{q})d}\\
            &\leqslant3^dC_0^{2m}d^\sigma\sum\limits_{L=1}^{\infty}2^{-\sigma L}
            \left(\frac{L}{d}\right)^{\sigma d}
            \left(1+\frac{L}{d}\right)^{(1-\frac{1}{q})d}\\
            &\leqslant3^dC_0^{2m+2d},
        \end{aligned}
        \label{shi-tongciweikuaiqiuhe}
    \end{equation}
    by \eqref{shi-duocishuqiuhe}, \eqref{shi-kuaitongyijie}, and \eqref{shi-zhishishuaijian}.

    For $d=0$, $\beta=0$. By \eqref{shi-shanjianzhiji}, \eqref{shi-fenkuaizhiji}, and \eqref{shi-shuangjinfenkuai},
    \begin{equation}
        \begin{aligned}
            A_{m,0}^-&=\{\eta\in\mathbb{N}_0^{(\mathbb{N})}:|\eta|=m-1,\ \mathrm{supp}\eta\subset I_0\},\\
            |A_{m,0}^-|&=\binom{|I_0|+m-2}{m-1}
            \leqslant2^{|I_0|+m-2}\leqslant2^{3m}.
        \end{aligned}
        \label{shi-shoukuaizhijishu}
    \end{equation}
    Apply \eqref{shi-zhijixishuguji} with $\textbf{u}=P_{I_0}\textbf{z}$. By \eqref{shi-shoukuaizhijishu}, \eqref{shi-kuaitongyijie}, and \eqref{shi-fuzhuchangshu},
    \begin{equation}
        \begin{aligned}
            \sum\limits_{\alpha\in A_{m,0}}|c_\alpha(G)\textbf{z}^\alpha|
            &\leqslant e^{2m}|A_{m,0}^-|^\sigma\|P_{I_0}\textbf{z}\|_X^m\|G\|\leqslant e^{2m}2^{3\sigma m}C_0^m\leqslant C_0^{2m}.
        \end{aligned}
        \label{shi-shoukuaixishuguji}
    \end{equation}
    Combining \eqref{shi-xishuhefenjie}, \eqref{shi-tongciweikuaiqiuhe}, and \eqref{shi-shoukuaixishuguji}, we obtain
    \begin{equation}
        \begin{aligned}
            \sum\limits_{|\alpha|=m}|c_\alpha(G)\textbf{z}^\alpha|
            &\leqslant C_0^{2m}+\sum\limits_{d=1}^{m}3^dC_0^{2m+2d}\leqslant(m+1)3^mC_0^{4m}\leqslant(6C_0^4)^m.
        \end{aligned}
        \label{shi-jingdianqiuhe}
    \end{equation}
    Put $C\triangleq6C_0^4$. By \eqref{shi-xishuhebudong}, \eqref{shi-yicixishuguji}, \eqref{shi-jingdianqiuhe}, and homogeneity, for every $m,n\in\mathbb{N}$ and $G=G\circ P_n$,
    \begin{equation}
        \sum\limits_{|\alpha|=m}|c_\alpha(G)\textbf{z}^\alpha|
        \leqslant C^mM(P_n\textbf{z})^m\|G\|
        \leqslant C^mM(\textbf{z})^m\|G\|.
        \label{shi-youxianchongpaiguji}
    \end{equation}
    Finally, for arbitrary $G\in\mathcal{P}^m(X)$, \eqref{shi-shouweisuosuo}, and \eqref{shi-youxianchongpaiguji} yield
    $$
    \begin{aligned}
        \sum\limits_{|\alpha|=m}|c_\alpha(G)\textbf{z}^\alpha|
        &=\lim\limits_{n\to\infty}
        \sum\limits_{\substack{|\alpha|=m\\\mathrm{supp}\alpha\subset\{1,\cdots,n\}}}
        |c_\alpha(G)\textbf{z}^\alpha|=\lim\limits_{n\to\infty}
        \sum\limits_{|\alpha|=m}|c_\alpha(G\circ P_n)\textbf{z}^\alpha|\\
        &\leqslant C^mM(\textbf{z})^m\sup\limits_{n\in\mathbb{N}}\|G\circ P_n\|
        \leqslant C^mM(\textbf{z})^m\|G\|.
    \end{aligned}
    $$
    This proves \eqref{shi-chongpaixishuguji}.

\label{yinli-suijiduoxiangshi}
Let $n,m\in\mathbb{N}$ with $m\geqslant2$. There are 
$\left( \varepsilon_{\alpha} \right)_{\alpha \in \mathbb{N}_{0}^{n} ,\left| \alpha \right| =m} \in \left\{ -1,1 \right\}^{\left| \left\{ \alpha \in \mathbb{N}_{0}^{n}:\left| \alpha \right| =m \right\} \right|}$ such that the polynomial
$$
R(\textbf{u})\triangleq
\sum\limits_{\substack{\alpha\in\mathbb{N}_0^n\\|\alpha|=m}}
\varepsilon_\alpha\frac{m!}{\alpha!}\textbf{u}^\alpha
$$
satisfies, simultaneously for $1\leqslant r\leqslant2$,
\begin{equation}
\sup\limits_{\|\textbf{u}\|_{\ell^r}\leqslant1}|R(\textbf{u})|
\leqslant16^{2(1-\frac{1}{r})}
(nm!\log m)^{1-\frac{1}{r}}.
\label{shi-suijiduoxiangshiguji}
\end{equation}

\label{yinli-shangjixianbijiao}
Fix $1<p\leqslant\infty$, $\textbf{z}\in X$, and
$N\in\mathbb{N}_0$. Suppose there exist $A,R>0$ such that
\begin{equation}
\sum\limits_{|\alpha|=m}|c_\alpha(G)\textbf{z}^\alpha|
\leqslant AR^m\|G\|
\label{shi-weibuzhishijiading}
\end{equation}
for every $m\geqslant2$ and every $G\in\mathcal{P}^m(X)$ depending only on finitely many coordinates $x_j$ with $j>N$.
Then
\begin{equation}
\limsup\limits_{n\to\infty}
\frac{\left(\sum\limits_{j=1}^{n}
\bigl((Q_N\textbf{z})_j^*\bigr)^{q}\right)^{\frac{1}{q}}}
{(\log(n+1))^{\sigma}}
\leqslant R.
\label{shi-weibushangjixian}
\end{equation}

Put $C\triangleq16$, $r\triangleq\min\{p,2\}$, and $\frac{1}{s}\triangleq\frac{1}{r}-\frac{1}{p}$, with $s=\infty$ when $p=r$. By \eqref{shi-fenleizhishu}, $0<\sigma=1-\frac{1}{r}\leqslant\frac{1}{2}$, $\frac{1}{r}=\frac{1}{s}+\frac{1}{p}$, and $\frac{1}{q}+\frac{1}{s}=1$. Fix $n,m\in\mathbb{N}$ with $m\geqslant2$. By \eqref{shi-suijiduoxiangshiguji} in Lemma~\ref{yinli-suijiduoxiangshi}, there exists a family
$
	(\varepsilon_\alpha)_{\substack{\alpha\in\mathbb{N}_0^n\\|\alpha|=m}}
	\in
	\{-1,1\}^{\{\alpha\in\mathbb{N}_0^n:\,|\alpha|=m\}}
$
	such that
	\begin{equation}
		\sup\limits_{\|\textbf{u}\|_{\ell^r}\leqslant1}
		\left|\sum\limits_{\substack{\alpha\in\mathbb{N}_0^n\\|\alpha|=m}}
		\varepsilon_\alpha\frac{m!}{\alpha!}\textbf{u}^\alpha\right|
		\leqslant16^{2\sigma}(nm!\log m)^\sigma
		\leqslant C(nm!\log m)^\sigma.
		\label{shi-suijicanshuguji}
	\end{equation}
	Choose $N<j_1<\cdots<j_n$, put $J\triangleq\{j_1,\cdots,j_n\}$, and let $\textbf{a}=(a_1,\cdots,a_n)\in\mathbb{C}^n$ satisfy $\|\textbf{a}\|_{\ell^s}\leqslant1$. H\"older's inequality, including the cases $s=\infty$ and $p=\infty$, gives
	$$
	\left\|(a_kx_{j_k})_{k=1}^n\right\|_{\ell^r}
	\leqslant\|\textbf{a}\|_{\ell^s}
	\left\|(x_{j_k})_{k=1}^n\right\|_{\ell^p}
	\leqslant\|\textbf{x}\|_X,
	\qquad \textbf{x}\in X.
	$$
	Define
	$$
	G_{\textbf{a}}(\textbf{x})\triangleq
	\sum\limits_{\substack{\alpha\in\mathbb{N}_0^n\\|\alpha|=m}}
	\varepsilon_\alpha\frac{m!}{\alpha!}
	\prod\limits_{k=1}^n(a_kx_{j_k})^{\alpha_k},
	\qquad \textbf{x}\in X.
	$$
	Then $G_{\textbf{a}}\in\mathcal{P}^m(X)$ depends only on the coordinates indexed by $J$, and \eqref{shi-suijicanshuguji} gives $\|G_{\textbf{a}}\|\leqslant C(nm!\log m)^\sigma$. For every $\beta\in\mathbb{N}_0^{(\mathbb{N})}$ with $|\beta|=m$,
	$$
	c_\beta(G_{\textbf{a}})=
	\begin{cases}
		\displaystyle
		\varepsilon_{(\beta_{j_1},\cdots,\beta_{j_n})}
		\frac{m!}{\beta!}\prod\limits_{k=1}^n a_k^{\beta_{j_k}},
		&\mathrm{supp}\beta\subset J,\\[5pt]
		0,&\mathrm{supp}\beta\not\subset J.
	\end{cases}
	$$
	The multinomial theorem and \eqref{shi-weibuzhishijiading} therefore yield
	\begin{equation}
		\begin{aligned}
		&\left(\sum\limits_{k=1}^n|a_kz_{j_k}|\right)^m
			=\sum\limits_{\substack{\alpha\in\mathbb{N}_0^n\\|\alpha|=m}}
			\frac{m!}{\alpha!}\prod\limits_{k=1}^n|a_kz_{j_k}|^{\alpha_k}\\
			&\quad =\sum\limits_{\substack{\beta\in\mathbb{N}_0^{(\mathbb{N})}\\|\beta|=m}}
			|c_\beta(G_{\textbf{a}})\textbf{z}^\beta| \leqslant AR^m\|G_{\textbf{a}}\|
			\\&\quad\leqslant AC R^m(nm!\log m)^\sigma.
		\end{aligned}
		\label{shi-duijiaoceshiguji}
	\end{equation}

	Put $S\triangleq\left\|(z_{j_k})_{k=1}^n\right\|_{\ell^q}$. By H\"older's inequality, $$\sum\limits_{k=1}^n|a_kz_{j_k}|\leqslant\|\textbf{a}\|_{\ell^s}S\leqslant S.$$If $q=1$, the choice $\textbf{a}=(1,\cdots,1)$ gives $\|\textbf{a}\|_{\ell^\infty}=1$ and $\sum\limits_{k=1}^n|a_kz_{j_k}|=S$. If $q>1$ and $S>0$, choose $a_k=\frac{|z_{j_k}|^{q-1}}{S^{q-1}}$, $1\leqslant k\leqslant n$. Since $s=\frac{q}{q-1}$,
	$$
	\|\textbf{a}\|_{\ell^s}^s
	=\frac{\sum\limits_{k=1}^n|z_{j_k}|^q}{S^q}=1,
	\qquad
	\sum\limits_{k=1}^n|a_kz_{j_k}|
	=\frac{\sum\limits_{k=1}^n|z_{j_k}|^q}{S^{q-1}}=S.
	$$
	For $S=0$, both sides of the following equality vanish. Thus \eqref{shi-duijiaoceshiguji} implies
	$$
	\begin{aligned}
		\left(\sum\limits_{k=1}^n|z_{j_k}|^q\right)^{\frac{1}{q}}
		&=\sup\limits_{\substack{\textbf{a}\in\mathbb{C}^n\\\|\textbf{a}\|_{\ell^s}\leqslant1}}
		\sum\limits_{k=1}^n|a_kz_{j_k}|\leqslant R(AC)^{\frac{1}{m}}n^{\frac{\sigma}{m}}
		(m!)^{\frac{\sigma}{m}}(\log m)^{\frac{\sigma}{m}}.
	\end{aligned}
	$$

	For every $F\subset\mathbb{N}$ with $|F|=n$, choose $H\subset\{N+1,N+2,\cdots\}\setminus F$ with $|H|=|F\cap\{1,\cdots,N\}|$, and put $\widetilde F\triangleq(F\setminus\{1,\cdots,N\})\cup H$. Then $\widetilde F\subset\{N+1,N+2,\cdots\}$, $|\widetilde F|=n$, and
	$$
	\sum\limits_{j\in F}|(Q_N\textbf{z})_j|^q
	=\sum\limits_{j\in F\setminus\{1,\cdots,N\}}|z_j|^q
	\leqslant\sum\limits_{j\in\widetilde F}|z_j|^q.
	$$
	Since $\textbf{z}\in X\subset c_0$, \eqref{shi-chongpaishangquejie} yields
	\begin{equation}
		\begin{aligned}
			&\left(\sum\limits_{j=1}^n\bigl((Q_N\textbf{z})_j^*\bigr)^q\right)^{\frac{1}{q}}
			=\sup\limits_{\substack{F\subset\mathbb{N}\\|F|=n}}
			\left(\sum\limits_{j\in F}|(Q_N\textbf{z})_j|^q\right)^{\frac{1}{q}}\\
			&\quad=\sup\limits_{N<j_1<\cdots<j_n}
			\left(\sum\limits_{k=1}^n|z_{j_k}|^q\right)^{\frac{1}{q}}\leqslant R(AC)^{\frac{1}{m}}n^{\frac{\sigma}{m}}
			(m!)^{\frac{\sigma}{m}}(\log m)^{\frac{\sigma}{m}}.
		\end{aligned}
		\label{shi-weibuchongpaijie}
	\end{equation}
Finally, set $m=\max\{2,\lceil\log(n+1)\rceil\}$. By the Stolz--Ces\`aro theorem,
$$
\lim\limits_{k\to\infty}
\frac{\log(k!)-k\log k}{k}
=-\lim\limits_{k\to\infty}
k\log\left(1+\frac{1}{k}\right)=-1.
$$
Hence $\frac{(k!)^{\frac{1}{k}}}{k}\longrightarrow e^{-1}$. Since $\frac{m}{\log(n+1)}\longrightarrow1$, we obtain
$$
n^{\frac{1}{m}}\longrightarrow e,
\qquad
\frac{(m!)^{\frac{1}{m}}}{\log(n+1)}
\longrightarrow e^{-1},
\qquad
(AC)^{\frac{1}{m}}(\log m)^{\frac{\sigma}{m}}
\longrightarrow1.
$$
Dividing \eqref{shi-weibuchongpaijie} by $(\log(n+1))^\sigma$ and taking the upper limit as $n\to\infty$ therefore gives
$$
\limsup\limits_{n\to\infty}
\frac{\left(\sum\limits_{j=1}^{n}
	\bigl((Q_N\textbf{z})_j^*\bigr)^q\right)^{\frac{1}{q}}}
{(\log(n+1))^\sigma}
\leqslant R\left(e\cdot e^{-1}\right)^\sigma=R.
$$
This establishes \eqref{shi-weibushangjixian}.

\label{mingti-youjiexingshoulian}
For $X,p,q,\sigma$ as in \eqref{shi-fenleizhishu}, one has
\begin{equation}
\mathrm{dom}H_b(X)
=\{\textbf{z}\in X:M(\textbf{z})<\infty\}.
\label{shi-youjiexingshoulian}
\end{equation}

\label{dingli-youjiexulieshoulian}
One has
\begin{equation}
\mathrm{dom}H(\ell^\infty)
=
\left\{\textbf{z}\in c_0:
\sup\limits_{n\geqslant1}
\frac{\sum\limits_{j=1}^{n}(z_j^*)^2}{\log(n+1)}<\infty\right\}.
\label{shi-youjiexulieshoulian}
\end{equation}
Moreover,
$$
\mathrm{dom}H(\ell^\infty)
=\mathrm{dom}H_b(c_0).
$$

Aron and Berner \cite[Proposition~1.1, p.~8]{AB78} prove that \begin{equation}
\{F|_{c_0}:F\in H(\ell^\infty)\}=H_b(c_0).
\label{shi-zhenghanshuxianzhi}
\end{equation}

Since
$\overline{\mathbb{C}^{(\mathbb{N})}}^{\,\ell^\infty}=c_0$,
\eqref{shi-bibaobaohan} gives
\begin{equation}
\mathrm{dom}H(\ell^\infty)\subset c_0.
\label{shi-shoulianlingjixian}
\end{equation}
Restriction from $\ell^\infty$ to $c_0$ leaves each $c_\alpha$
unchanged, because the finite-dimensional restrictions defining it
coincide. Together with \eqref{shi-shoulianlingjixian} and
\eqref{shi-youjiexingshoulian} for $p=\infty$,
this gives \eqref{shi-youjiexulieshoulian}.

\label{tuilun-youjiexuliedengjia}
One has
\begin{equation}
\mathrm{dom}H_b(\ell^\infty)
=\mathrm{dom}H(\ell^\infty)
=\mathrm{dom}H_b(c_0).
\label{shi-sangeshoulianyudengjia}
\end{equation}
In particular,
$\mathrm{dom}H_b(\ell^\infty)$ is the set on the right-hand side of
\eqref{shi-youjiexulieshoulian}.

\label{tuilun-jingdianquanyu}
Let $X=\ell^p$ with $1\leqslant p<\infty$, or let $X=c_0$,
and let $O\subset X$ be a Reinhardt domain. If $X=\ell^1$, then
\begin{equation}
\mathrm{dom}H(O)=O.
\label{shi-yikehequanyu}
\end{equation}
If $X=\ell^p$ with $1<p\leqslant2$, then
\begin{equation}
\mathrm{dom}H(O)
=
\left\{\textbf{z}\in O:
\lim\limits_{n\to\infty}
\frac{\sum\limits_{j=1}^{n}z_j^*}
{(\log(n+1))^{1-\frac{1}{p}}}=0\right\}.
\label{shi-xiaozhishuquanyu}
\end{equation}
If $X=\ell^p$ with $2<p<\infty$, then
\begin{equation}
\mathrm{dom}H(O)
=
\left\{\textbf{z}\in O:
\lim\limits_{n\to\infty}
\frac{\sum\limits_{j=1}^{n}(z_j^*)^{\frac{2p}{p+2}}}
{(\log(n+1))^{\frac{p}{p+2}}}=0\right\}.
\label{shi-dazhishuquanyu}
\end{equation}
If $X=c_0$, then
\begin{equation}
\mathrm{dom}H(O)
=
\left\{\textbf{z}\in O:
\lim\limits_{n\to\infty}
\frac{\sum\limits_{j=1}^{n}(z_j^*)^2}{\log(n+1)}=0\right\}.
\label{shi-lingjixianquanyu}
\end{equation}
In each case, for every $f\in H(O)$ and
$\textbf{z}\in\mathrm{dom}H(O)$,
\eqref{shi-juduishoulian} and \eqref{shi-hanshubiaoshi} hold.

\label{mingti-youjiexulieqiu}
One has
\begin{equation}
\mathrm{dom}H(B_{\ell^\infty})
=
\left\{\textbf{z}\in B_{c_0}:
\limsup\limits_{n\to\infty}
\frac{\sum\limits_{j=1}^{n}(z_j^*)^2}{\log(n+1)}<1\right\}.
\label{shi-youjiexulieqiu}
\end{equation}
Moreover, for every $f\in H(B_{\ell^\infty})$ and every
$\textbf{z}$ in the set on the right of
\eqref{shi-youjiexulieqiu},
\eqref{shi-juduishoulian} and \eqref{shi-hanshubiaoshi} hold.

\par\medskip\noindent\textbf{Step 1}\par\nopagebreak[4]

Since
$\overline{\mathbb{C}^{(\mathbb{N})}}^{\,\ell^\infty}=c_0$,
\eqref{shi-bibaobaohan}, applied to
$O=B_{\ell^\infty}$, gives
\begin{equation}
\mathrm{dom}H(B_{\ell^\infty})\subset B_{c_0}.
\label{shi-qiushoulianlingjixian}
\end{equation}
For every $f\in H(B_{\ell^\infty})$, we have
\begin{equation}
c_\alpha(f|_{B_{c_0}})=c_\alpha(f),
\qquad \alpha\in\mathbb{N}_0^{(\mathbb{N})}.
\label{shi-xianzhixishuyizhi}
\end{equation}
Consequently, whenever the monomial series of $f$ is absolutely
convergent at $\textbf{z}\in B_{c_0}$,
Proposition~\ref{mingti-jishubiaoshi} identifies its sum with $f(\textbf{z})$
by \eqref{shi-hanshubiaoshi}. 

By \cite[Theorem~2.2\,(a)]{BDFMS17}, together with
\cite[(14) and (16)]{BDFMS17}, we have, for
$X\in\{c_0,\ell^\infty\}$ and $\textbf{w}\in B_{c_0}$,
\begin{equation}
	\limsup\limits_{n\to\infty}
	\frac{\sum\limits_{j=1}^{n}(w_j^*)^2}{\log(n+1)}<1
	\quad\Longrightarrow\quad
	\textbf{w}\in\mathrm{dom}H^\infty(B_X).
	\label{shi-yuzhichongfentiaojian}
\end{equation}

\par\medskip\noindent\textbf{Step 2}\par\nopagebreak[4]

Let $\textbf{z}\in\mathrm{dom}H(B_{\ell^\infty})$. By \eqref{shi-qiushoulianlingjixian}, $\textbf{z}\in B_{c_0}$. Since $H_b(B_{\ell^\infty})\subset H(B_{\ell^\infty})$, Lemma~\ref{yinli-bituguji} gives $A>0$ and $0<\rho<1$ such that
\begin{equation}
\sum\limits_{\alpha\in\mathbb{N}_0^{(\mathbb{N})}}
|c_\alpha(f)\textbf{z}^\alpha|
\leqslant A\|f\|_\rho,\qquad f\in H_b(B_{\ell^\infty}).
\label{shi-qiubituguji}
\end{equation}
Fix $m\geqslant2$, $n\in\mathbb{N}$, and $G\in\mathcal{P}^m(c_0)$ with $G=G\circ P_n$. Put $\widetilde G(\textbf{x})\triangleq G(P_n\textbf{x})$ for $\textbf{x}\in\ell^\infty$. Then $\widetilde G|_{B_{\ell^\infty}}\in H_b(B_{\ell^\infty})$. By \eqref{shi-youxianzuobiaoyantuo}, \eqref{shi-qiubituguji}, and homogeneity,
\begin{equation}
\begin{aligned}
\sum\limits_{|\alpha|=m}|c_\alpha(G)\textbf{z}^\alpha|
&=\sum\limits_{|\alpha|=m}|c_\alpha(\widetilde G)\textbf{z}^\alpha|
\leqslant A\|\widetilde G\|_\rho\\
&=A\rho^m\|\widetilde G\|_{\mathcal{P}^m(\ell^\infty)}
=A\rho^m\|G\|_{\mathcal{P}^m(c_0)}.
\end{aligned}
\label{shi-qiucishujie}
\end{equation}
By \eqref{shi-qiucishujie} and Lemma~\ref{yinli-shangjixianbijiao},
$$
\limsup\limits_{n\to\infty}
\frac{\sum\limits_{j=1}^{n}(z_j^*)^2}{\log(n+1)}
\leqslant\rho^2<1.
$$
This proves the necessary condition in \eqref{shi-youjiexulieqiu}.

\par\medskip\noindent\textbf{Step 3}\par\nopagebreak[4]

By \cite[p.~455]{GMZ12}, a
function in $H(B_{c_0})$ extends holomorphically to $B_{\ell^\infty}$
if and only if it belongs to $H_b(B_{c_0})$. Therefore, for each $f\in H(B_{\ell^\infty})$ and $0<r<1$, we have
\begin{equation}
\sup\limits_{\textbf{w}\in rB_{c_0}}|f(\textbf{w})|<\infty.
\label{shi-xianzhijubuyoujie}
\end{equation}
Let $\textbf{z}\in B_{c_0}$ satisfy the upper-limit condition in
\eqref{shi-youjiexulieqiu}. Choose $r$ such that
\begin{equation}
\|\textbf{z}\|_{\ell^\infty}<r<1,
\qquad
\limsup\limits_{n\to\infty}
\frac{\sum\limits_{j=1}^{n}(z_j^*)^2}{\log(n+1)}<r^2.
\label{shi-suofangbanjing}
\end{equation}
Fix $f\in H(B_{\ell^\infty})$, and define
$$
h(\textbf{w})\triangleq f(r\textbf{w}),\qquad\textbf{w}\in B_{c_0}.
$$
By \eqref{shi-xianzhijubuyoujie},
$h\in H^\infty(B_{c_0})$.
It is easy to see that
\begin{equation}
c_\alpha(h)=r^{|\alpha|}c_\alpha(f),
\qquad\alpha\in\mathbb{N}_0^{(\mathbb{N})}.
\label{shi-suofangxishu}
\end{equation}
Also, \eqref{shi-suofangbanjing} implies
$\frac{\textbf{z}}{r}\in B_{c_0}$ and
$$
\limsup\limits_{n\to\infty}
\frac{\sum\limits_{j=1}^{n}\left(\frac{z_j^*}{r}\right)^2}
{\log(n+1)}
=\frac{1}{r^2}\limsup\limits_{n\to\infty}
\frac{\sum\limits_{j=1}^{n}(z_j^*)^2}{\log(n+1)}<1.
$$
By \eqref{shi-yuzhichongfentiaojian},
$\frac{\textbf{z}}{r}\in\mathrm{dom}H^\infty(B_{c_0})$.
Consequently, \eqref{shi-suofangxishu} yields
$$
\sum\limits_{\alpha\in\mathbb{N}_0^{(\mathbb{N})}}
|c_\alpha(f)\textbf{z}^\alpha|
=\sum\limits_{\alpha\in\mathbb{N}_0^{(\mathbb{N})}}
\left|c_\alpha(h)\left(\frac{\textbf{z}}{r}\right)^\alpha\right|
<\infty.
$$
Since $f$ was arbitrary, this proves the reverse inclusion in
\eqref{shi-youjiexulieqiu}. Equation
\eqref{shi-xianzhixishuyizhi} and
Proposition~\ref{mingti-jishubiaoshi}, applied to
$f|_{B_{c_0}}$ at $\textbf{z}$, now give
\eqref{shi-hanshubiaoshi}.

\label{zhuji-linjieqingxing}
The strict inequality in \eqref{shi-youjiexulieqiu}
characterizes $\mathrm{dom}H(B_{\ell^\infty})$.
For bounded holomorphic functions, however, a complete characterization
is still not known. The available result is due to
\cite[Theorem~2.2\,(a)--(b)]{BDFMS17}:
$$
	\begin{aligned}
		\left\{\textbf{z}\in B_{c_0}:
		\limsup\limits_{n\to\infty}
		\frac{\sum\limits_{j=1}^{n}(z_j^*)^2}{\log(n+1)}<1\right\}
		&\subseteq\mathrm{dom}H^\infty(B_{\ell^\infty})\\
		&\subsetneq
		\left\{\textbf{z}\in B_{c_0}:
		\limsup\limits_{n\to\infty}
		\frac{\sum\limits_{j=1}^{n}(z_j^*)^2}{\log(n+1)}\leqslant1\right\}.
	\end{aligned}
$$

\label{dingli-l1-zuijiabanjing}
	Let $t\in\left(\frac{1}{2},1\right)$ be the unique solution of
	\begin{equation}
		-\log(1-t)=2t.
		\label{shi-l1-zuijiacanshu}
	\end{equation}
	Every function $f$ holomorphic in a neighbourhood of $\textbf{0}$
	in  $\ell^1$ satisfies
	\begin{equation}
		\sqrt{t(1-t)}\,r(f,\textbf{0})
		\leqslant |r|(f,\textbf{0})
		\leqslant r(f,\textbf{0}).
		\label{shi-l1-zuijiabanjing}
	\end{equation}
	Both constants are optimal.

By $-\log(1-t)=2t$ and
$$
\sup\limits_{s>0}\frac{\log(1+s^2)}{2s}
=\frac{-\log(1-t)}{2\sqrt{\frac{t}{1-t}}}
=\sqrt{t(1-t)},
$$
we have
	\begin{equation}
		1+s^2\leqslant e^{2s\sqrt{t(1-t)}},
		\qquad s\geqslant0.
		\label{shi-l1-biaoliangzhishijie}
	\end{equation}
	We shall also use
	\begin{equation}
b^{2a}\geqslant a!b^{a}\geqslant a!b\left( b-1 \right) \cdots \left( b-a+1 \right) =\left( a! \right)^{2} \binom{b}{a},
		\qquad a,b\in\mathbb{N}_0,b\geqslant a.
		\label{shi-l1-zhengshujuguji}
	\end{equation}
	Finally, Stirling's formula and
	\eqref{shi-l1-zuijiacanshu} give
	\begin{equation}
\begin{aligned}
	&\begin{aligned}\lim\limits_{m\to \infty} \frac{\binom{m^{2}}{m}^{\frac{1}{m}}}{4^{\frac{1}{m}}e\, m\sqrt{t(1-t)} \left( \log 8+2m^{2}\log (1+24m) \right)^{\frac{1}{2m}}}&\end{aligned}\\ &\  =\lim\limits_{m\to \infty} \frac{\left\lceil \frac{m}{t} \right\rceil}{\left( m! \right)^{\frac{1}{m}} \binom{\left\lceil \frac{m}{t} \right\rceil}{m}^{\frac{1}{2m}}} =\frac{1}{\sqrt{t\left( 1-t \right)}}.\end{aligned}
		\label{shi-l1-caiyanggenjixian}
	\end{equation}


	\par\medskip\noindent\textbf{Step 1}\par\nopagebreak[4]

	We prove that, for all integers $k\geqslant m\geqslant2$,
	\begin{equation}
		\|P\|\leqslant\|P^{\#}\|
		\leqslant
		\frac{k^m}{m!\binom{k}{m}^{\frac{1}{2}}}\|P\|,
		\qquad P\in\mathcal{P}^m(\ell^1).
		\label{shi-l1-jingquexishushangjie}
	\end{equation}
The lower bound in \eqref{shi-l1-jingquexishushangjie} is immediate from
$$
|P(\textbf{z})|
\leqslant P^{\#}(|\textbf{z}|),
\qquad \textbf{z}\in B_{\ell^1}.
$$
To prove the upper bound, by the same truncation argument as in
Lemma~\ref{yinli-gujituiguang}, it suffices to consider
$P\in\mathcal{P}^m(\ell^1)$ satisfying $P=P\circ P_n$ for some
$n\in\mathbb{N}$. Fix
	$\textbf{x}=(x_1,\cdots,x_n)\in[0,+\infty)^n$ with
	$\sum\limits_{j=1}^n x_j=1$.
	For every $\beta\in\mathbb{N}_0^n$ with $|\beta|=k$, 
\begin{equation}
	\begin{aligned}
		&\frac{1}{k^{2m}}
		\sum\limits_{\substack{\alpha\in\mathbb{N}_0^n\\|\alpha|=m}}
		|c_\alpha(P)|^2
		\prod\limits_{j=1}^n\beta_j^{2\alpha_j}=
		\sum\limits_{\substack{\alpha\in\mathbb{N}_0^n\\|\alpha|=m}}
		\left|
		c_\alpha(P)
		\prod\limits_{j=1}^n
		\left(\frac{\beta_j}{k}\right)^{\alpha_j}
		\right|^2\\
		&\quad=
		\frac{1}{(2\pi)^n}
		\int\limits_{[0,2\pi]^n}
		\left|
		\sum\limits_{\substack{\alpha\in\mathbb{N}_0^n\\|\alpha|=m}}
		c_\alpha(P)
		\prod\limits_{j=1}^n
		\left(
		\frac{\beta_j}{k}e^{\mathrm{i}\theta_j}
		\right)^{\alpha_j}
		\right|^2
		\,\mathrm{d}\theta_1\cdots\mathrm{d}\theta_n\\
		&\quad=
		\frac{1}{(2\pi)^n}
		\int\limits_{[0,2\pi]^n}
		\left|
		P\left(
		\sum\limits_{j=1}^n
		\frac{\beta_j}{k}e^{\mathrm{i}\theta_j}e_j
		\right)
		\right|^2
		\,\mathrm{d}\theta_1\cdots\mathrm{d}\theta_n\\
		&\quad\leqslant
		\frac{1}{(2\pi)^n}
		\int\limits_{[0,2\pi]^n}
		\|P\|^2
		\left\|
		\sum\limits_{j=1}^n
		\frac{\beta_j}{k}e^{\mathrm{i}\theta_j}e_j
		\right\|_{\ell^1}^{2m}
		\,\mathrm{d}\theta_1\cdots\mathrm{d}\theta_n\\
		&\quad=
		\frac{1}{(2\pi)^n}
		\int\limits_{[0,2\pi]^n}
		\|P\|^2
		\left(
		\sum\limits_{j=1}^n\frac{\beta_j}{k}
		\right)^{2m}
		\,\mathrm{d}\theta_1\cdots\mathrm{d}\theta_n\\
		&\quad=
		\frac{1}{(2\pi)^n}
		\int\limits_{[0,2\pi]^n}
		\|P\|^2
		\left(\frac{|\beta|}{k}\right)^{2m}
		\,\mathrm{d}\theta_1\cdots\mathrm{d}\theta_n
		=\|P\|^2,
	\end{aligned}\label{shi-714}
\end{equation}
	where the second equality follows from Parseval's identity.	For $|\alpha|=m$, inequality
	\eqref{shi-l1-zhengshujuguji} implies
\begin{equation}
	\begin{aligned}
		&\sum\limits_{\substack{\beta\in\mathbb{N}_0^n\\|\beta|=k}}
		\frac{k!}{\beta!}\textbf{x}^{\beta}
		\prod\limits_{j=1}^n\beta_j^{2\alpha_j}\geqslant
		(\alpha!)^2
		\sum\limits_{\substack{\beta\in\mathbb{N}_0^n\\
				|\beta|=k,\ \beta\geqslant\alpha}}
		\frac{k!}{\beta!}\textbf{x}^{\beta}
		\prod\limits_{j=1}^n\binom{\beta_j}{\alpha_j}\\
		&\quad=
		\alpha!k!\textbf{x}^{\alpha}
		\sum\limits_{\substack{\gamma\in\mathbb{N}_0^n\\|\gamma|=k-m}}
		\frac{\textbf{x}^{\gamma}}{\gamma!}
		=
		\alpha!\frac{k!}{(k-m)!}\textbf{x}^{\alpha}.\label{shi-713}
	\end{aligned}
\end{equation}
	Here $\beta\geqslant\alpha$ is understood $\beta_{j} \geqslant \alpha_{j} ,1\leqslant j\leqslant n$.

By \eqref{shi-713}, \eqref{shi-714} and $\sum\limits_{\substack{\beta\in\mathbb{N}_0^n\\|\beta|=k}}
\frac{k!}{\beta!}\textbf{x}^{\beta}=\| \textbf{x} \|_{\ell^{{}1}}^{k} =1$, we have
	$$
\begin{aligned}
	\|P\|^2
	&=
	\|P\|^2
	\sum\limits_{\substack{\beta\in\mathbb{N}_0^n\\|\beta|=k}}
	\frac{k!}{\beta!}\textbf{x}^{\beta}\geqslant
	\frac{1}{k^{2m}}
	\sum\limits_{\substack{\beta\in\mathbb{N}_0^n\\|\beta|=k}}
	\frac{k!}{\beta!}\textbf{x}^{\beta}
	\sum\limits_{\substack{\alpha\in\mathbb{N}_0^n\\|\alpha|=m}}
	|c_\alpha(P)|^2
	\prod\limits_{j=1}^n\beta_j^{2\alpha_j}\\
	&=
	\frac{1}{k^{2m}}
	\sum\limits_{\substack{\alpha\in\mathbb{N}_0^n\\|\alpha|=m}}
	|c_\alpha(P)|^2
	\sum\limits_{\substack{\beta\in\mathbb{N}_0^n\\|\beta|=k}}
	\frac{k!}{\beta!}\textbf{x}^{\beta}
	\prod\limits_{j=1}^n\beta_j^{2\alpha_j}\geqslant
	\frac{k!}{k^{2m}(k-m)!}
	\sum\limits_{\substack{\alpha\in\mathbb{N}_0^n\\|\alpha|=m}}
	\alpha!|c_\alpha(P)|^2\textbf{x}^{\alpha},
\end{aligned}
	$$
Then the Cauchy--Schwarz inequality gives
	$$
	\begin{aligned}
		\bigl(P^{\#}(\textbf{x})\bigr)^2
		&\leqslant
		\left(
		\sum\limits_{\substack{\alpha\in\mathbb{N}_0^n\\|\alpha|=m}}
		\alpha!|c_\alpha(P)|^2\textbf{x}^{\alpha}
		\right)
		\left(
		\sum\limits_{\substack{\alpha\in\mathbb{N}_0^n\\|\alpha|=m}}
		\frac{\textbf{x}^{\alpha}}{\alpha!}
		\right)\leqslant
		\frac{k^{2m}(k-m)!}{m!k!}\|P\|^2,
	\end{aligned}
	$$
	which gives the upper
	bound in \eqref{shi-l1-jingquexishushangjie}.



	\par\medskip\noindent\textbf{Step 2}\par\nopagebreak[4]

	Let $f$ be holomorphic in a neighbourhood of $\textbf{0}$,
	and let $H_m$ be its homogeneous Taylor polynomials.
	By local boundedness of $f$ and \eqref{shi-qicikexiguji},
	$$
	\limsup\limits_{m\to\infty}\|H_m\|^{\frac{1}{m}}<+\infty.
	$$
	Apply \eqref{shi-l1-jingquexishushangjie} to $H_m$ with
	$k=\left\lceil\frac{m}{t}\right\rceil$ and using
	\eqref{shi-l1-caiyanggenjixian}, gives
	$$
	\begin{aligned}
		\limsup\limits_{m\to\infty}\|H_m\|^{\frac{1}{m}}
		&\leqslant
		\limsup\limits_{m\to\infty}\|H_m^{\#}\|^{\frac{1}{m}}\leqslant
		\frac{1}{\sqrt{t(1-t)}}
		\limsup\limits_{m\to\infty}\|H_m\|^{\frac{1}{m}}.
	\end{aligned}
	$$
Thus we have completed the proof of \eqref{shi-l1-zuijiabanjing}.

	\par\medskip\noindent\textbf{Step 3}\par\nopagebreak[4]

To prove the optimality of the lower bound, fix $ m\geqslant2$.
	For $\textbf{u}=\left( u_{i} \right)_{1\leqslant i\leqslant m^{2}}\in\mathbb{C}^{m^{2}}$ with
	$\|\textbf{u}\|_{\ell^1}\leqslant1$,
	\eqref{shi-l1-biaoliangzhishijie} give
	$$
	\begin{aligned}
		&\left(\frac{m^2}{t(1-t)}\right)^m
		\sum\limits_{\substack{F\subset\{1,\cdots,m^{2}\}\\|F|=m}}
		\prod\limits_{j\in F}|u_j|^2\leqslant
		\prod\limits_{j=1}^{m^{2}}
		\left(1+\frac{m^2|u_j|^2}{t(1-t)}\right)\leqslant
		e^{2m\sum\limits_{j=1}^{m^{2}}|u_j|}
		\leqslant e^{2m}.
	\end{aligned}
	$$
	Consequently,
	\begin{equation}
		(m!)^2
		\sum\limits_{\substack{F\subset\{1,\cdots,m^{2}\}\\|F|=m}}
		\prod\limits_{j\in F}|u_j|^2
		\leqslant
		(m!)^2
		\left(\frac{e\sqrt{t(1-t)}}{m}\right)^{2m}.
		\label{shi-l1-suijifangcha}
	\end{equation}

	Apply Lemma~\ref{yinli-duoxiangshiwang} and let $\mathcal{N}$ be the resulting finite subset
	of the closed $\ell^2$ unit ball in $\mathbb{C}^{m^{2}}$.
	For every $m$-homogeneous polynomial $P$ on $\mathbb{C}^{m^{2}}$,
	the polynomial
	$\textbf{u}\mapsto P(u_1^2,\cdots,u_{m^{2}}^2)$
	is $2m$-homogeneous. Moreover,
	$$
	\left\{
	(u_1^2,\cdots,u_{m^{2}}^2):
	\textbf{u}\in\mathbb{C}^{m^{2}},\
	\|\textbf{u}\|_{\ell^2}\leqslant1
	\right\}
	=
	\left\{
	\textbf{v}\in\mathbb{C}^{m^{2}}:
	\|\textbf{v}\|_{\ell^1}\leqslant1
	\right\}.
	$$

	The cited lemma therefore gives
	\begin{equation}
		\begin{gathered}
			|\mathcal{N}|\leqslant(1+24m)^{2m^{2}},\qquad	\|P\|
			=
			\sup\limits_{\|\textbf{u}\|_{\ell^2}\leqslant1}
			|P(u_1^2,\cdots,u_{m^{2}}^2)|
			\leqslant
			2\max\limits_{\textbf{u}\in\mathcal{N}}
			|P(u_1^2,\cdots,u_{m^{2}}^2)|.
		\end{gathered}
		\label{shi-l1-danchunxingwang}
	\end{equation}

	Let
	$
	(\varepsilon_F)_{\substack{F\subset\{1,\cdots,m^{2}\}\\|F|=m}}
	$
	be independent random variables satisfying
	$$
	\mathbb{P}(\varepsilon_F=1)
	=
	\mathbb{P}(\varepsilon_F=-1)
	=
	\frac{1}{2},
	\qquad
	F\subset\{1,\cdots,m^{2}\},\quad |F|=m.
	$$and put
	$$
	R_m(\textbf{u})\triangleq
	m!\sum\limits_{\substack{F\subset\{1,\cdots,m^{2}\}\\|F|=m}}
	\varepsilon_F\prod\limits_{j\in F}u_j.
	$$
	By \eqref{shi-suijiweigailv} and 
	\eqref{shi-l1-suijifangcha}, for each $\|\textbf{u}\|_{\ell^1}\leqslant1,\lambda>0$,
	$$
	\begin{aligned}
		\mathbb{P}\bigl(|R_m(\textbf{u})|>\lambda\bigr)
		&\leqslant
		\mathbb{P}\left(
		|\mathrm{Re}\,R_m(\textbf{u})|>\frac{\lambda}{\sqrt{2}}
		\right)
		+
		\mathbb{P}\left(
		|\mathrm{Im}\,R_m(\textbf{u})|>\frac{\lambda}{\sqrt{2}}
		\right)\\
		&\leqslant
		2e^{
			-\frac{(\frac{\lambda}{\sqrt{2}})^2}
			{2	\sum\limits_{\substack{F\subset\{1,\cdots,m^{2}\}\\|F|=m}}
	\left(
				\mathrm{Re}\left(
				m!\prod\limits_{j\in F}u_j
				\right)
				\right)^2}
		}
		+
		2e^{
			-\frac{(\frac{\lambda}{\sqrt{2}})^2}
			{2	\sum\limits_{\substack{F\subset\{1,\cdots,m^{2}\}\\|F|=m}}
				\left(
				\mathrm{Im}\left(
				m!\prod\limits_{j\in F}u_j
				\right)
				\right)^2}
		}\\
		&\leqslant
		4e^{-\frac{\lambda^2}
			{4(m!)^2
				\left(
				\frac{e\sqrt{t(1-t)}}{m}
				\right)^{2m}}}.
	\end{aligned}
	$$

	Take
	$$
	\lambda\triangleq
	2m!\left(\frac{e\sqrt{t(1-t)}}{m}\right)^m
	\sqrt{\log8+2m^{2}\log(1+24m)}.
	$$
Hence, by \eqref{shi-l1-danchunxingwang}, 
$$
\begin{aligned}\mathbb{P} \left( \frac{\| R_m\|}{2} >\lambda \right)&\leqslant \mathbb{P} \left( \max\limits_{\textbf{u} \in \mathcal{N}} |R_m(u_{1}^{2},\cdots ,u_{m^{2}}^{2})|>\lambda \right)\\ &\leqslant 4|\mathcal{N} |e^{-\log 8-2m^{2}\log (1+24m)}\\ &\leqslant 4(1+24m)^{2m^{2}}e^{-\log 8-2m^{2}\log (1+24m)}\\ &=\frac{1}{2} ,\end{aligned}
$$
	Thus there is a $	
	(\varepsilon_F)_{\substack{F\subset\{1,\cdots,m^{2}\}\\|F|=m}}
	$ such that
	$$
	\|R_m\|
	\leqslant
	4m!\left(\frac{e\sqrt{t(1-t)}}{m}\right)^m
	\sqrt{\log8+2m^{2}\log(1+24m)}.
	$$
	Note that
	$$
\| R_{m}^{\#}\| \geqslant R_{m}^{\#}\left( \left( \frac{1}{m^{2}} \right)_{1\leqslant i\leqslant m^{2}} \right) =\frac{m!\binom{m^{2}}{m}}{(m^{2})^{m}}.
	$$
	Together with \eqref{shi-l1-jingquexishushangjie}, this gives
	\begin{equation}
	\begin{aligned}\sqrt[m]{\frac{\frac{m!\binom{m^{2}}{m}}{(m^{2})^{m}}}{4m!\left( \frac{e\sqrt{t(1-t)}}{m} \right)^{m} \sqrt{\log 8+2m^{2}\log (1+24m)}}}&\leqslant \frac{\| R_{m}^{\#}\|^{\frac{1}{m}}}{\| R_{m}\|^{\frac{1}{m}}} \leqslant \frac{\left\lceil \frac{m}{t} \right\rceil}{\left( m! \right)^{\frac{1}{m}} \binom{\left\lceil \frac{m}{t} \right\rceil}{m}^{\frac{1}{2m}}} .\end{aligned}
		\label{shi-l1-jingqueliangbian}
	\end{equation}
Applying
	\eqref{shi-l1-caiyanggenjixian}, we conclude that
	\begin{equation}
		\lim\limits_{m\to\infty}
		\left(
		\frac{\|R_m^{\#}\|}{\|R_m\|}
		\right)^{\frac{1}{m}}
		=
		\frac{1}{\sqrt{t(1-t)}}.
		\label{shi-l1-jingquezengzhang}
	\end{equation}

	\par\medskip\noindent\textbf{Step 4}\par\nopagebreak[4]

	Put $n_1=0$ and $n_m=n_{m-1}+m^2$ for $m\geqslant2$,
	and define
	$$
	H_0=H_1=0,
	\qquad
	H_m(\textbf{z})\triangleq
	\frac{R_m(z_{n_{m-1}+1},\cdots,z_{n_m})}{\|R_m\|},
	\qquad m\geqslant2.
	$$
Note that
	$$
	\|H_m\|=1,
	\qquad
	\|H_m^{\#}\|=\frac{\|R_m^{\#}\|}{\|R_m\|},
	\qquad
	|H_m(\textbf{z})|
	\leqslant
	\|(P_{n_m}-P_{n_{m-1}})\textbf{z}\|_{\ell^1}^m.
	$$
	Set
	$$
	f(\textbf{z})\triangleq
	\sum\limits_{m=2}^{\infty}H_m(\textbf{z}).
	$$

	Fix $\textbf{x}\in\ell^1$. By \eqref{shi-weibushoulian},
	choose $M\geqslant2$ such that
	$\|Q_{n_{M-1}}\textbf{x}\|_{\ell^1}\leqslant\frac{1}{4}$.
	For $\|\textbf{y}-\textbf{x}\|_{\ell^1}<\frac{1}{4}$
	and $m\geqslant M$, 
$$
\begin{aligned}
	\|(P_{n_m}-P_{n_{m-1}})\textbf{y}\|_{\ell^1}
	&\leqslant
	\|(P_{n_m}-P_{n_{m-1}})\textbf{x}\|_{\ell^1}
	+\|(P_{n_m}-P_{n_{m-1}})(\textbf{y}-\textbf{x})\|_{\ell^1}\\
	&\leqslant
	\|Q_{n_{m-1}}\textbf{x}\|_{\ell^1}
	+\|\textbf{y}-\textbf{x}\|_{\ell^1}\leqslant
	\|Q_{n_{M-1}}\textbf{x}\|_{\ell^1}
	+\|\textbf{y}-\textbf{x}\|_{\ell^1}\leqslant\frac{1}{2}.
\end{aligned}
$$
	Hence $\sum\limits_{m=M}^{\infty} \left| H_{m}(\textbf{y} ) \right|\leqslant \sum\limits_{m=M}^{\infty} \frac{1}{2^{m}} <\infty$
	and \eqref{shi-quanchunjixian} gives $f\in H(\ell^1)$. One readily checks that  $H_m$ is the $m$-homogeneous Taylor polynomial of $f$ at $\textbf{0}$. By \eqref{shi-l1-jingquezengzhang},
	$$
	r(f,\textbf{0})=1,
	\qquad
	|r|(f,\textbf{0})=\sqrt{t(1-t)}.
	$$
	Thus the lower constant in \eqref{shi-l1-zuijiabanjing}
	cannot be increased.

		\par\medskip\noindent\textbf{Step 5}\par\nopagebreak[4]

To prove the optimality of the upper bound, consider
$$
g(\textbf{z})\triangleq
\sum\limits_{m=2}^{\infty}z_m^m\in H(\ell^1),
\qquad
\sup\limits_{\|\textbf{z}\|_{\ell^1}\leqslant1}
|g(\textbf{z})|\leqslant1.
$$
For $m\geqslant2$, the $m$-homogeneous Taylor polynomial of $g$
at $\textbf{0}$ is $H_m(\textbf{z})=z_m^m$. Hence
$
\|H_m\|=\|H_m^{\#}\|=1,
$
which gives
$
r(g,\textbf{0})=|r|(g,\textbf{0})=1.
$
This completes the proof of
Theorem~\ref{dingli-l1-zuijiabanjing}.

\label{dingli-duoxiangshishoulianyu}
	For every $1\leqslant p\leqslant\infty$,
	\begin{equation}
		\mathrm{dom}\mathcal{P}^{1}(\ell^p)=\ell^p,
		\qquad
		\mathrm{dom}\mathcal{P}^{1}(c_0)=c_0.
		\label{shi-yiciduoxiangshishoulian}
	\end{equation}
	For every $m\in\mathbb{N}$,
	\begin{equation}
		\mathrm{dom}\mathcal{P}^{m}(\ell^1)=\ell^1.
		\label{shi-yikeduoxiangshishoulian}
	\end{equation}
	For every $m\geqslant2$,
	\begin{equation}
		\mathrm{dom}\mathcal{P}^{m}(c_0)
		=
		\mathrm{dom}\mathcal{P}^{m}(\ell^\infty)
		=
		\ell_{\frac{2m}{m-1},\infty}.
		\label{shi-youjieduoxiangshishoulian}
	\end{equation}
	For $1<p<\infty$ and $m\geqslant2$, define
	\begin{equation}
		\frac{1}{q_m}
		\triangleq
		\frac{1}{p}+
		\frac{m-1}{m}
		\left(1-\frac{1}{\min\{p,2\}}\right).
		\label{shi-duoxiangshiqm}
	\end{equation}
	Then
	\begin{equation}
		\begin{aligned}
			\mathrm{dom}\mathcal{P}^{m}(\ell^p)
			&=
			\ell_{q_m,\max\{p,m\}}
		\end{aligned}
		\label{shi-duoxiangshishoulianyu}
	\end{equation}

\raggedbottom
By Remark~\ref{rem-11}, it remains to prove
\eqref{shi-duoxiangshishoulianyu}.
Fix $1<p<\infty$ and $m\geqslant2$, and put
\begin{equation}
\sigma\triangleq1-\frac{1}{\min\{p,2\}},
\qquad r\triangleq\max\{p,m\}.
\label{shi-duoxiangshi-canshu}
\end{equation}
Thus 
\begin{equation}
\frac{1}{q_m}=\frac{1}{p}+\frac{m-1}{m}\sigma,
\qquad 1<q_m<p\leqslant r,
\qquad r\geqslant m.
\label{shi-duoxiangshi-q-sigma}
\end{equation}
For an $m$-homogeneous polynomial $G$, write
$$
S_{\textbf{z}}(G)\triangleq
\sum\limits_{\substack{\alpha\in\mathbb{N}_0^{(\mathbb{N})}\\|\alpha|=m}}
|c_\alpha(G)\textbf{z}^{\alpha}|,
$$
allowing the value $+\infty$.
We first prove that there exist $c,C>0$, depending only on
$m,p$, such that, for every $\textbf{z}\in\mathbb{C}^{(\mathbb{N})}$,
\begin{equation}
\begin{aligned}
c\left(\sum\limits_{n=1}^{\infty}
n^{\frac{r}{q_m}-1}(z_n^*)^r\right)^{\frac{m}{r}}
&\leqslant
\sup\limits_{\substack{
G\in\mathscr{P}_0\cap\mathcal{P}^{m}(\ell^p)\\\|G\|\leqslant1}}
S_{\textbf{z}}(G)&\leqslant
C\left(\sum\limits_{n=1}^{\infty}
n^{\frac{r}{q_m}-1}(z_n^*)^r\right)^{\frac{m}{r}}.
\end{aligned}
\label{shi-duoxiangshi-liangceguji}
\end{equation}

\par\medskip\noindent\textbf{Step 1}\par\nopagebreak[4]
Without loss of generality, we may assume
$z_1\geqslant z_2\geqslant\cdots\geqslant0$.
Put
$$
D_k\triangleq\{2^k,\cdots,2^{k+1}-1\},
\qquad k\in\mathbb{N}_0.
$$
Note that for every $k\in \mathbb{N}_0$, 
$$
2^{\frac{kr}{q_m}}z_{2^{k+1}}^r
\leqslant\sum\limits_{n\in D_k}n^{\frac{r}{q_m}-1}z_n^r
\leqslant2^{\frac{r}{q_m}-1}
\left(2^{\frac{k}{q_m}}z_{2^k}\right)^r.
$$
Summing the above inequalities over $k=0,1,2,\cdots$, we obtain
\begin{equation}
2^{1-\frac{r}{q_m}}
\sum\limits_{n=1}^{\infty}n^{\frac{r}{q_m}-1}z_n^r
\leqslant\sum\limits_{k=0}^{\infty}
\left(2^{\frac{k}{q_m}}z_{2^k}\right)^r
\leqslant\left(1+2^{\frac{r}{q_m}}\right)
\sum\limits_{n=1}^{\infty}n^{\frac{r}{q_m}-1}z_n^r.
\label{shi-duoxiangshi-erjinzhi}
\end{equation}

\par\medskip\noindent\textbf{Step 2}\par\nopagebreak[4]

We prove the upper estimate in \eqref{shi-duoxiangshi-liangceguji}.
Suppose first that $p\geqslant m$.
Put $\textbf{u} \triangleq \left( j^{\frac{m-1}{2m}}z_{j} \right)_{j\in \mathbb{N}}=\left( u_{j} \right)_{j\in \mathbb{N}}$ and
$\textbf{v} \triangleq \left( j^{-\frac{m-1}{2m}} \right)_{j\in \mathbb{N}}$.
By \eqref{shi-youjieduoxiangshishoulian},
$\textbf{v}\in\mathrm{dom}\mathcal{P}^m(c_0)$.
The closed graph argument in the proof of
Lemma~\ref{yinli-bituguji}, applied to $\mathcal{P}^m(c_0)$,
therefore gives $C_m>0$ such that
\begin{equation}
	S_{\textbf{v}}(Q)\leqslant C_m\|Q\|\label{shi-yy}
\end{equation} for every
$Q\in\mathcal{P}^m(c_0)$.

For $G\in\mathscr{P}_0\cap\mathcal{P}^m(\ell^p)$,
note that
$$
\widetilde{G}:c_0\to\mathbb{C},
\quad
\textbf{x}=(x_j)_{j\in\mathbb N}
\mapsto G\left((u_jx_j)_{j\in\mathbb N}\right)
$$
belongs to $\mathcal{P}^m(c_0)$.
Applying \eqref{shi-yy} and using
$c_\alpha(\widetilde{G})
=\textbf{u}^\alpha c_\alpha(G)$
for every $\alpha\in\mathbb{N}_0^{(\mathbb{N})}$,
we obtain
$$
\begin{aligned}S_{\textbf{z}}(G)&=S_{\textbf{v}}(\widetilde{G} )\leqslant C_{m}\| \widetilde{G} \| \leqslant C_{m}\sup\limits_{\textbf{x} \in B_{c_{0}}} \| G\| \left\| (u_{j}x_{j})_{j\in \mathbb{N}} \right\|_{\ell^{p}}^{m}\\ &\leqslant C_{m}\| G\| \| \textbf{u} \|_{\ell^{p}}^{m} =C_{m}\| G\| \left( \sum\limits_{j=1}^{\infty} j^{\frac{p\left( m-1 \right)}{2m}}z_{j}^{p} \right)^{\frac{m}{p}}\\ &=C_{m}\| G\| \left( \sum\limits_{j=1}^{\infty} j^{\frac{p}{q_{m}} -1}z_{j}^{p} \right)^{\frac{m}{p}} =C_{m}\| G\| \left( \sum\limits_{j=1}^{\infty} j^{\frac{r}{q_{m}} -1}z_{j}^{r} \right)^{\frac{m}{p}}\end{aligned}
$$

Now suppose that $1<p<m$.
Fix $G\in\mathscr{P}_0\cap\mathcal{P}^m(\ell^p)$ and choose
$N\in\mathbb{N}_0$ such that
$G=G\circ P_{2^{N+1}-1}$ and
$\mathrm{supp}\textbf{z}\subset\{1,\cdots,2^{N+1}-1\}$.
For $0\leqslant k_1\leqslant\cdots\leqslant k_m\leqslant N$, put
$$
A_{k_1,\cdots,k_m}\triangleq\left\{
\sum\limits_{j=1}^{m}e_{i_j}:
i_1\leqslant\cdots\leqslant i_m,\quad
i_j\in D_{k_j},\ 1\leqslant j\leqslant m
\right\}.\qquad \textbf{w}\triangleq
\sum\limits_{k\in\{k_1,\cdots,k_m\}}
2^{-\frac{k}{p}}\sum\limits_{i\in D_k}e_i.
$$
Then
$$
\left\{
\alpha\in\mathbb{N}_0^{(\mathbb{N})}:
|\alpha|=m,\quad
\mathrm{supp}\,\alpha\subset\{1,\cdots,2^{N+1}-1\}
\right\}
=
\bigsqcup\limits_{0\leqslant k_1\leqslant\cdots\leqslant k_m\leqslant N}
A_{k_1,\cdots,k_m}.
$$
Similarly to \eqref{shi-shanjianzhiji}, we define
$$
A_{k_1,\cdots,k_m}^-
\triangleq\left\{
\sum\limits_{j=1}^{m-1}e_{i_j}:
i_1\leqslant\cdots\leqslant i_{m-1},\quad
i_j\in D_{k_j},\ 1\leqslant j\leqslant m-1
\right\}.
$$
One has
$$
|A_{k_1,\cdots,k_m}^-|
\leqslant\prod\limits_{j=1}^{m-1}|D_{k_j}|
=2^{\sum\limits_{j=1}^{m-1}k_j},\qquad\| \textbf{w} \|_{\ell^{p}}^{p} =\sum\limits_{k\in \left\{ k_{1},k_{2},\cdots ,k_{m} \right\}} \frac{\left| D_{k} \right|}{2^{k}} =\left| \left\{ k_{1},\cdots ,k_{m} \right\} \right| \leqslant m.
$$

Applying \eqref{shi-zhijixishuguji}  and 
\eqref{shi-duoxiangshi-q-sigma}, we obtain
$$
\begin{aligned}\sum\limits_{\alpha \in A_{k_{1},\cdots ,k_{m}}} |c_{\alpha}(G)\textbf{z}^{\alpha} |&=\sum\limits_{\alpha \in A_{k_{1},\cdots ,k_{m}}} \left( |c_{\alpha}(G)|\prod\limits_{j=1}^{m} \left| z_{i_{j}} \right| \right)\leqslant \sum\limits_{\alpha \in A_{k_{1},\cdots ,k_{m}}} \left( |c_{\alpha}(G)|\prod\limits_{j=1}^{m} \left| z_{2^{k_{j}}} \right| \right)\\ &=\sum\limits_{\alpha \in A_{k_{1},\cdots ,k_{m}}} \left( |c_{\alpha}(G)|\cdot \prod\limits_{j=1}^{m} 2^{-\frac{k_{j}}{p}}\cdot \prod\limits_{j=1}^{m} \left( 2^{\frac{k_{j}}{p}}z_{2^{k_{j}}} \right) \right)\\ &=\sum\limits_{\alpha \in A_{k_{1},\cdots ,k_{m}}} \left( |c_{\alpha}(G)|\cdot \textbf{w}^{\alpha} \prod\limits_{j=1}^{m} \left( 2^{\frac{k_{j}}{p}}z_{2^{k_{j}}} \right) \right)\\ &\leqslant e^{2m}|A_{k_{1},\cdots ,k_{m}}^{-}|^{\sigma}\left\| \textbf{w} \right\|_{\ell^{p}}^{m} \| G\| \prod\limits_{j=1}^{m} \left( 2^{\frac{k_{j}}{p}}z_{2^{k_{j}}} \right)\\ &\leqslant e^{2m}m^{\frac{m}{p}}\| G\| 2^{\sigma \sum\limits_{j=1}^{m-1} k_{j}}\prod\limits_{j=1}^{m} \left( 2^{\frac{k_{j}}{p}}z_{2^{k_{j}}} \right)\\ &=e^{2m}m^{\frac{m}{p}}\| G\| 2^{\sigma \sum\limits_{j=1}^{m-1} k_{j}}\prod\limits_{j=1}^{m} \left( 2^{\frac{k_{j}}{q_{m}} -\frac{\sigma \left( m-1 \right) k_{j}}{m}}z_{2^{k_{j}}} \right)\\ &=e^{2m}m^{\frac{m}{p}}\| G\| 2^{-\frac{\sigma}{m} \sum\limits_{j=1}^{m-1} (k_{m}-k_{j})}\prod\limits_{j=1}^{m} \left( 2^{\frac{k_{j}}{q_{m}}}z_{2^{k_{j}}} \right) .\end{aligned}
$$
Summing the preceding inequality over
$0\leqslant k_1\leqslant\cdots\leqslant k_m\leqslant N$
and using $z_{2^k}=0$ for $k>N$, we obtain
\begin{equation}
S_{\textbf{z}}(G)\leqslant e^{2m}m^{\frac{m}{p}}\|G\|
\sum\limits_{0\leqslant k_1\leqslant\cdots\leqslant k_m}
2^{-\frac{\sigma}{m}\sum\limits_{j=1}^{m-1}(k_m-k_j)}
\prod\limits_{j=1}^{m}
\left(2^{\frac{k_j}{q_m}}z_{2^{k_j}}\right).
\label{shi-duoxiangshi-fenkuai}
\end{equation}
We have
\begin{equation}
\begin{aligned}
	&\sum\limits_{0\leqslant k_1\leqslant\cdots\leqslant k_m}
	2^{-\frac{\sigma}{m}\sum\limits_{j=1}^{m-1}(k_m-k_j)}
	\prod\limits_{j=1}^{m}
	\left(2^{\frac{k_j}{q_m}}z_{2^{k_j}}\right)
	\\
	&\qquad=
	\sum\limits_{0=k_1\leqslant\cdots\leqslant k_m}
	\prod\limits_{j=1}^{m-1}
	2^{-\frac{\sigma j}{m}(k_{j+1}-k_j)}
	\sum\limits_{k=0}^{\infty}
	\prod\limits_{j=1}^{m}
	\left(2^{\frac{k+k_j}{q_m}}z_{2^{k+k_j}}\right)
	\\
	&\qquad\leqslant
	\frac{1}{m}
	\sum\limits_{0=k_1\leqslant\cdots\leqslant k_m}
	\prod\limits_{j=1}^{m-1}
	2^{-\frac{\sigma j}{m}(k_{j+1}-k_j)}
	\sum\limits_{j=1}^{m}
	\sum\limits_{k=0}^{\infty}
	\left(2^{\frac{k+k_j}{q_m}}z_{2^{k+k_j}}\right)^m
	\\
	&\qquad\leqslant
	\sum\limits_{0=k_1\leqslant\cdots\leqslant k_m}
	\prod\limits_{j=1}^{m-1}
	2^{-\frac{\sigma j}{m}(k_{j+1}-k_j)}
	\sum\limits_{k=0}^{\infty}
	\left(2^{\frac{k}{q_m}}z_{2^k}\right)^m
	\\
	&\qquad=
	\prod\limits_{j=1}^{m-1}
	\left(\sum\limits_{k=0}^{\infty}2^{-\frac{\sigma j}{m}k}\right)
	\sum\limits_{k=0}^{\infty}
	\left(2^{\frac{k}{q_m}}z_{2^k}\right)^m
	\\
	&\qquad=
	\prod\limits_{j=1}^{m-1}
	\left(1-2^{-\frac{\sigma j}{m}}\right)^{-1}
	\sum\limits_{k=0}^{\infty}
	\left(2^{\frac{k}{q_m}}z_{2^k}\right)^m,
\end{aligned}
\label{shi-duoxiangshi-xianglinchaguji}
\end{equation}
where the first equality follows by subtracting the smallest index from each $k_j$ and using
$\sum\limits_{j=1}^{m-1}(k_m-k_j)
=\sum\limits_{j=1}^{m-1}j(k_{j+1}-k_j)$,
and the first inequality follows from the arithmetic--geometric mean inequality.

Combining \eqref{shi-duoxiangshi-fenkuai},
\eqref{shi-duoxiangshi-xianglinchaguji}, and
\eqref{shi-duoxiangshi-erjinzhi}, with $r=m$, proves the upper
estimate in \eqref{shi-duoxiangshi-liangceguji}.

\par\medskip\noindent\textbf{Step 3}\par\nopagebreak[4]

We prove the lower estimate in \eqref{shi-duoxiangshi-liangceguji}.
Put $C_0\triangleq16^{2\sigma}(m!\log m)^\sigma$.
For each $n\in\mathbb{N}$, let $R$ be the polynomial given by
Lemma~\ref{yinli-suijiduoxiangshi}, namely,
$$
R(\textbf{u})=
\sum\limits_{\substack{\alpha\in\mathbb{N}_0^n\\|\alpha|=m}}
\varepsilon_\alpha\frac{m!}{\alpha!}\textbf{u}^{\alpha},
\qquad\varepsilon_\alpha\in\{-1,1\}.
$$
Applying the classical inequality
$$
\|\textbf{u}\|_{\ell^{\min\{p,2\}}}
\leqslant
n^{\frac{1}{\min\{p,2\}}-\frac{1}{p}}
\|\textbf{u}\|_{\ell^p},
\quad \textbf{u}\in\mathbb{C}^n
$$
together with \eqref{shi-suijiduoxiangshiguji}, we obtain
$$
\begin{aligned}\sup\limits_{\| \textbf{u} \|_{\ell^{p}} \leqslant 1} |R(\textbf{u} )|&\leqslant \sup\limits_{\| \textbf{u} \|_{\ell^{\min\{p,2\}}} \leqslant n^{\frac{1}{\min\{p,2\}} -\frac{1}{p}}} |R(\textbf{u} )|\\ &=\sup\limits_{\| \textbf{u} \|_{\ell^{\min\{p,2\}}} \leqslant 1} \left| R\left( n^{\frac{1}{\min\{p,2\}} -\frac{1}{p}}\textbf{u} \right) \right|\\ &=n^{\frac{m}{\min\{p,2\}} -\frac{m}{p}} \sup\limits_{\| \textbf{u} \|_{\ell^{\min\{p,2\}}} \leqslant 1} \left| R\left( \textbf{u} \right) \right|\\ &\leqslant C_{0}n^{\frac{m}{\min\{p,2\}} -\frac{m}{p}}n^{\sigma}=C_{0}n^{m\left( 1-\frac{1}{q_{m}} \right)}.\end{aligned}
$$
For each $k\in\mathbb{N}_0$, choose such a polynomial $R_k$
in $n=2^k$ variables and define
$$
G_k(\textbf{x})\triangleq
\frac{R_k(x_{2^k},\cdots,x_{2^{k+1}-1})}
{C_0\,2^{km\left(1-\frac{1}{q_m}\right)}},
\qquad\textbf{x}\in\ell^p.
$$
Then $|G_k(\textbf{x})|\leqslant
\|P_{D_k}\textbf{x}\|_{\ell^p}^m$ and
\begin{equation}
	S_{\textbf{z}}(G_k)
	=\frac{\left(\sum\limits_{j\in D_k}z_j\right)^m}{C_0\,2^{km\left(1-\frac{1}{q_m}\right)}}
	\geqslant\frac{\left(2^kz_{2^{k+1}}\right)^m}{C_0\,2^{km\left(1-\frac{1}{q_m}\right)}}
	=\frac{1}{C_0}\left(2^{\frac{k}{q_m}}z_{2^{k+1}}\right)^m.
	\label{shi-duoxiangshi-kuai-zhixishu}
\end{equation}
and \begin{equation}
S_{\textbf{z}}(G_0)=\frac{z_1^m}{C_0}.
\label{shi-duoxiangshi-shoukuai}
\end{equation}

Let $\left(\frac{r}{m}\right)'=
\begin{cases}
	\frac{r}{r-m},&r>m,\\
	\infty,&r=m.
\end{cases}$.
For $N\in\mathbb{N}_0$ and
$\textbf{a}=(a_0,\cdots,a_N)\in\mathbb{C}^{N+1}$,
H\"older's inequality, $r\geqslant p$ and monotonicity of $q\mapsto \left\| \cdot \right\|_{\ell^{q}}$ gives
$$
\begin{aligned}\left|\sum\limits_{k=0}^{N} a_{k}G_{k}\left( \textbf{x} \right) \right|&\leqslant \sum\limits_{k=0}^{N} |a_{k}|\| P_{D_{k}}\textbf{x} \|_{\ell^{p}}^{m} \leqslant \| \textbf{a} \|_{\ell^{\left( \frac{r}{m} \right)^{\prime}}} \left( \sum\limits_{k=0}^{N} \| P_{D_{k}}\textbf{x} \|_{\ell^{p}}^{r} \right)^{\frac{m}{r}}\\ &\leqslant \| \textbf{a} \|_{\ell^{\left( \frac{r}{m} \right)^{\prime}}} \left( \sum\limits_{k=0}^{N} \| P_{D_{k}}\textbf{x} \|_{\ell^{p}}^{p} \right)^{\frac{m}{p}} \leqslant \| \textbf{a} \|_{\ell^{\left( \frac{r}{m} \right)^{\prime}}} \| \textbf{x} \|_{\ell^{p}}^{m}.\end{aligned}
$$

Thus 
$$\left\| \sum\limits_{k=0}^{N} a_{k}G_{k}\left( \cdot \right) \right\|\leqslant\|\textbf{a}\|_{\ell^{\left(\frac{r}{m}\right)'}},\qquad S_{\textbf{z}}\left(\sum\limits_{k=0}^{N} a_{k}G_{k}\left( \cdot \right) \right)=\sum\limits_{k=0}^{N} |a_{k}|S_{\textbf{z}}(G_{k}).$$
Finite-dimensional duality, followed by taking the supremum over
$N$, therefore yields
\begin{equation}
\begin{aligned}
	\sup\limits_{\substack{G\in\mathscr{P}_0\cap\mathcal{P}^{m}(\ell^p)\\\|G\|\leqslant1}}S_{\textbf{z}}(G)
	&\geqslant\sup\limits_{N\geqslant0}\sup\limits_{\|\textbf{a}\|_{\ell^{\left(\frac{r}{m}\right)'}}\leqslant1}S_{\textbf{z}}\left(\sum\limits_{k=0}^{N} a_{k}G_{k}\left( \cdot \right) \right)
	=\sup\limits_{N\geqslant0}\sup\limits_{\|\textbf{a}\|_{\ell^{\left(\frac{r}{m}\right)'}}\leqslant1}\sum\limits_{k=0}^{N}|a_k|S_{\textbf{z}}(G_k)\\
	&=\sup\limits_{N\geqslant0}\left(\sum\limits_{k=0}^{N}S^{\frac{r}{m}}_{\textbf{z}}(G_k)\right)^{\frac{m}{r}}
	=\left(\sum\limits_{k=0}^{\infty}S^{\frac{r}{m}}_{\textbf{z}}(G_k)\right)^{\frac{m}{r}}.
\end{aligned}
\label{shi-duoxiangshi-kuai-duiou}
\end{equation}
By \eqref{shi-duoxiangshi-kuai-zhixishu} and
\eqref{shi-duoxiangshi-shoukuai},
$$
\begin{aligned}
\sum\limits_{k=0}^{\infty}
\left(2^{\frac{k}{q_m}}z_{2^k}\right)^r
&=z_1^r+2^{\frac{r}{q_m}}
\sum\limits_{k=0}^{\infty}
\left(2^{\frac{k}{q_m}}z_{2^{k+1}}\right)^r\leqslant C_0^{\frac{r}{m}}\left(1+2^{\frac{r}{q_m}}\right)
\sum\limits_{k=0}^{\infty}S^{\frac{r}{m}}_{\textbf{z}}(G_k).
\end{aligned}
$$
Together with \eqref{shi-duoxiangshi-erjinzhi} and
\eqref{shi-duoxiangshi-kuai-duiou}, this proves the lower estimate
in \eqref{shi-duoxiangshi-liangceguji}.


\par\medskip\noindent\textbf{Step 4}\par\nopagebreak[4]

First, $\ell_{q_m,r}\subset\ell^p$. Indeed, for $\textbf{z}\in\ell_{q_m,r}$, since $r\geqslant p> q_m$ and $$\sum\limits_{j=1}^{n}j^{\frac{r}{q_m}-1}\geqslant\sum\limits_{j=1}^{n}\int\limits_{j-1}^{j}t^{\frac{r}{q_m}-1}\,\mathrm{d}t
=\int\limits_0^n t^{\frac{r}{q_m}-1}\,\mathrm{d}t
=\frac{q_m}{r}n^{\frac{r}{q_m}},$$ we have
$$
\begin{aligned}
	\sum\limits_{n=1}^{\infty}(z_n^*)^p
	&=\sum\limits_{n=1}^{\infty}n^{-\frac{p}{q_m}}
	\left(n^{\frac{r}{q_m}}(z_n^*)^r\right)^{\frac{p}{r}}
	\leqslant\sum\limits_{n=1}^{\infty}n^{-\frac{p}{q_m}}
	\left(\frac{r}{q_m}\sum\limits_{j=1}^{n}j^{\frac{r}{q_m}-1}(z_n^*)^r\right)^{\frac{p}{r}}\\
	&\leqslant\sum\limits_{n=1}^{\infty}n^{-\frac{p}{q_m}}
	\left(\frac{r}{q_m}\sum\limits_{j=1}^{n}j^{\frac{r}{q_m}-1}(z_j^*)^r\right)^{\frac{p}{r}}\\
	&\leqslant\left(\frac{r}{q_m}\sum\limits_{j=1}^{\infty}j^{\frac{r}{q_m}-1}(z_j^*)^r\right)^{\frac{p}{r}}
	\sum\limits_{n=1}^{\infty}n^{-\frac{p}{q_m}}<\infty.
\end{aligned}
$$


Arguing as in the proof of Lemma~\ref{yinli-gujituiguang},
we extend the upper estimate in \eqref{shi-duoxiangshi-liangceguji}
to $\textbf{z}\in\ell_{q_m,r}$ and
$G\in\mathcal{P}^m(\ell^p)$. Consequently,
$$
S_{\textbf{z}}(G)\leqslant C\|G\|
\left(\sum\limits_{j=1}^{\infty}
j^{\frac{r}{q_m}-1}(z_j^*)^r\right)^{\frac{m}{r}}<\infty,
$$
which proves
$\ell_{q_m,r}\subseteq\mathrm{dom}\mathcal{P}^m(\ell^p)$.



Conversely, let $\textbf{z}=\left( z_{i} \right)_{i\in \mathbb{N}}\in\mathrm{dom}\mathcal{P}^m(\ell^p)$.
By the same closed graph argument as in the proof of
Lemma~\ref{yinli-bituguji}, applied to the coefficient map
$G\mapsto(c_\alpha(G)\textbf{z}^{\alpha})_{|\alpha|=m}$
on the Banach space $\mathcal{P}^m(\ell^p)$,
there exists $K>0$ such that
\begin{equation}
	S_{\textbf{z}}(G)\leqslant K\|G\|,
	\qquad G\in\mathcal{P}^m(\ell^p).
	\label{shi-duoxiangshi-bitu}
\end{equation}

Since $S_{P_n\textbf{z}}(G)\leqslant S_{\textbf{z}}(G)$, the lower
estimate in \eqref{shi-duoxiangshi-liangceguji} implies
$$
c\left(\sum\limits_{j=1}^{\infty}
j^{\frac{r}{q_m}-1}\bigl((P_n\textbf{z})_j^*\bigr)^r
\right)^{\frac{m}{r}}\leqslant K.
$$
As $\textbf{z}\in\ell^p\subset c_0$,
$(P_n\textbf{z})_j^*\uparrow z_j^*$ for every $j\in \mathbb{N}$.
Monotone convergence yields
$$
\sum\limits_{j=1}^{\infty}j^{\frac{r}{q_m}-1}(z_j^*)^r
\leqslant\left(\frac{K}{c}\right)^{\frac{r}{m}}<\infty.
$$
Thus $\mathrm{dom}\mathcal{P}^m(\ell^p)\subseteq\ell_{q_m,r}$,
which completes the proof of \eqref{shi-duoxiangshishoulianyu}.
